(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["audio"]||{};var a=d["papers"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="paper-a-streamable-neural-audio-codec-with-2025"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-streamable-neural-audio-codec-with-2025-sec-1\">一 · 问题现场：一路实时语音在服务端的十二毫秒预算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-streamable-neural-audio-codec-with-2025-sec-2\">二 · 旧栈的量化器结构为什么与流式推进冲突</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-streamable-neural-audio-codec-with-2025-sec-3\">三 · 残差多级量化的机制：把一次大查询拆成 K 次小查询</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-streamable-neural-audio-codec-with-2025-sec-4\">四 · 因果卷积与帧间状态缓存：首包延迟与音频总长解耦</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-streamable-neural-audio-codec-with-2025-sec-5\">五 · 旧栈非改不可的工程理由：三条代价无法靠加卡摊薄</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-streamable-neural-audio-codec-with-2025-sec-6\">六 · 失败模式：把折中当免费午餐</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-streamable-neural-audio-codec-with-2025-sec-7\">七 · 请求形态：帧到达节奏与不可攒批约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-streamable-neural-audio-codec-with-2025-sec-8\">八 · 并发：状态缓存乘以路数的显存账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-streamable-neural-audio-codec-with-2025-sec-9\">九 · 单帧延迟：K 次串行查询的线性抬升</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-streamable-neural-audio-codec-with-2025-sec-10\">十 · 长尾：上尾而非均值决定 SLO</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-streamable-neural-audio-codec-with-2025-sec-11\">十一 · 方案反过来限制负载：码本容量与码率的闭环</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-streamable-neural-audio-codec-with-2025-sec-12\">十二 · 测量口径清单与不可核验项</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-streamable-neural-audio-codec-with-2025-sec-13\">十三 · 帧到达节奏如何反向约束量化级数与并发上限</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-streamable-neural-audio-codec-with-2025-sec-14\">十四 · 从码本查表到 Tensor Core：RSVQ 的算子分解</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-streamable-neural-audio-codec-with-2025-sec-15\">十五 · 数据类型选择：FP16、BF16、FP8 与 NVFP4 在编解码器里的分工</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-streamable-neural-audio-codec-with-2025-sec-16\">十六 · Blackwell 特性映射：tcgen05、TMEM 与 2-SM MMA</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-streamable-neural-audio-codec-with-2025-sec-17\">十七 · 单帧延迟的分解与精度档位的代价核算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-streamable-neural-audio-codec-with-2025-sec-18\">十八 · 状态缓存、显存与并发：精度选择如何反噬容量</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-streamable-neural-audio-codec-with-2025-sec-19\">十九 · 权重账本：码本常驻与分级存储</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-streamable-neural-audio-codec-with-2025-sec-20\">二十 · 状态缓存账本：随并发线性增长的那一项</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-streamable-neural-audio-codec-with-2025-sec-21\">二十一 · 分页、压缩、复用、卸载：四类手段的适用边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-streamable-neural-audio-codec-with-2025-sec-22\">二十二 · 带宽瓶颈定位：每帧的字节账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-streamable-neural-audio-codec-with-2025-sec-23\">二十三 · 可复算的显存预算模板</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-streamable-neural-audio-codec-with-2025-sec-24\">二十四 · 与 SLO 的耦合：状态缓存决定的是抖动而非均值</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-streamable-neural-audio-codec-with-2025-sec-25\">二十五 · 流式编解码的显存账本：状态缓存、码本常驻与串行查询的代价边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-streamable-neural-audio-codec-with-2025-sec-26\">二十六 · 逐帧到达下的批处理边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-streamable-neural-audio-codec-with-2025-sec-27\">二十七 · chunked prefill 在音频侧的对应物</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-streamable-neural-audio-codec-with-2025-sec-28\">二十八 · 优先级与抢占：谁让出算力</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-streamable-neural-audio-codec-with-2025-sec-29\">二十九 · 分离式预填/解码的音频映射</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-streamable-neural-audio-codec-with-2025-sec-30\">三十 · 尾延迟的三个抓手</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-streamable-neural-audio-codec-with-2025-sec-31\">三十一 · 时延与吞吐的取舍落点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-streamable-neural-audio-codec-with-2025-sec-32\">三十二 · 帧到达即处理的调度边界：连续批处理为何在这里失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-streamable-neural-audio-codec-with-2025-sec-33\">三十三 · 切分对象不是矩阵，是帧与状态</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-streamable-neural-audio-codec-with-2025-sec-34\">三十四 · NVLink 5 与 NVSwitch：把 All-to-All 压进机柜</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-streamable-neural-audio-codec-with-2025-sec-35\">三十五 · All-Reduce 在此处基本无事可做</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-streamable-neural-audio-codec-with-2025-sec-36\">三十六 · NIXL 传输：把状态缓存搬对地方</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-streamable-neural-audio-codec-with-2025-sec-37\">三十七 · 通信何时成为瓶颈：三个判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-streamable-neural-audio-codec-with-2025-sec-38\">三十八 · 拓扑选择的工程结论</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-streamable-neural-audio-codec-with-2025-sec-39\">三十九 · 并行切分与通信：编解码器为何几乎不碰 All-to-All</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-streamable-neural-audio-codec-with-2025-sec-40\">四十 · 精度塌陷：残差链断裂的三种形态</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-streamable-neural-audio-codec-with-2025-sec-41\">四十一 · OOM：状态缓存是随并发线性增长的隐性成本</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-streamable-neural-audio-codec-with-2025-sec-42\">四十二 · 批抖动与尾延迟：帧到达即处理的代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-streamable-neural-audio-codec-with-2025-sec-43\">四十三 · 静默降级：播放缓冲欠载与质量档位的隐性切换</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-streamable-neural-audio-codec-with-2025-sec-44\">四十四 · 监控面与定位顺序：从端到端指标拆到单级查询</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-streamable-neural-audio-codec-with-2025-sec-45\">四十五 · 回滚的工程边界：什么能动，什么不能动</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-streamable-neural-audio-codec-with-2025-sec-46\">四十六 · 先把“基准”拆成六个可独立变化的轴</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-streamable-neural-audio-codec-with-2025-sec-47\">四十七 · 首包延迟的正确分解与不可比的三种情形</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-streamable-neural-audio-codec-with-2025-sec-48\">四十八 · 吞吐、并发与显存：三个量的耦合关系</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-streamable-neural-audio-codec-with-2025-sec-49\">四十九 · 功耗与硬件档位：为什么“同模型不同档”不可直接比</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-streamable-neural-audio-codec-with-2025-sec-50\">五十 · 指标口径的陷阱：哪些提升是机制性的，哪些是口径性的</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-streamable-neural-audio-codec-with-2025-sec-51\">五十一 · 在 Blackwell 上落地这套口径的最小检查清单</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-streamable-neural-audio-codec-with-2025-sec-52\">五十二 · 流式编解码器的容量边界：串行查询、状态缓存与不可比的“提升”</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-streamable-neural-audio-codec-with-2025-sec-53\">五十三 · 迁移到别的编解码器：先看量化器的“可拆性”</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-streamable-neural-audio-codec-with-2025-sec-54\">五十四 · 迁移到别的领域：状态缓存的语义必须重新定义</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-streamable-neural-audio-codec-with-2025-sec-55\">五十五 · 规模上限：三个独立的饱和点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-streamable-neural-audio-codec-with-2025-sec-56\">五十六 · 与 Blackwell 推理栈的接口边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-a-streamable-neural-audio-codec-with-2025-sec-57\">五十七 · 不适用场景与判断准则</button></li></ol></nav><figure class=\"diagram\" data-fig=\"paper-pipeline\"><svg style=\"max-width:551px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 551.0 423\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"469.0\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">请求到达后音频按固定帧长切分，编码器因果卷积逐帧提取特征并下采样。</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"469.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">第一级标量量化器对特征每个维度独立量化，输出粗粒度索引与残差。</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"469.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">后续矢量量化级在小码本上量化残差，逐级累加逼近原始特征。</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"469.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">量化索引打包为码流，按帧写入发送缓冲，供接收端逐帧拉取。</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"469.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">解码器读取码流，因果反卷积结合帧间状态缓存逐帧重建波形。</text><line x1=\"82.0\" y1=\"342.2\" x2=\"82.0\" y2=\"359.2\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 358.2 L 86.5 358.2 L 82.0 366.2 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"366.2\" width=\"469.0\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"388.7\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"392.9\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">6</text><text x=\"75.0\" y=\"393.9\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">重建帧直接进入播放缓冲，首包在首帧解码完成后即可输出。</text></svg><figcaption><b>流水线</b> · 从输入到输出的数据流；每一步的模块与代价在正文展开。</figcaption></figure>\n<h3 id=\"paper-a-streamable-neural-audio-codec-with-2025-sec-1\">一 · 问题现场：一路实时语音在服务端的十二毫秒预算</h3>\n<p>设想一个在线会议或实时语音助手的接入节点：每路会话的音频以固定帧长切分，帧一到就必须编码、打包、发送；对端每收到一帧码流，就要立刻解码并推入播放缓冲。这里的时间预算不是“整段音频处理完要多久”，而是“单帧从编码到解码必须落在多少毫秒内”。首包延迟由单帧编码加单帧解码的耗时决定，端到端抖动容忍度则由播放缓冲深度兜底。工程上，这意味着推理栈必须按帧推进、按会话隔离状态，任何“等攒够一段再算”的设计都会直接击穿 SLO。旧方案在这个现场暴露的第一个矛盾，是离线编解码器的整段依赖与逐帧到达的输入节律根本不匹配。</p>\n<p>旧方案的主流做法是单级大码本矢量量化加非因果卷积（或整段注意力）编解码器：编码器一次看完整段音频，量化器在一个庞大的码本上做一次最近邻查询，解码器依赖双向上下文重建波形。它在离线重建质量上有优势，但推理栈的代价结构完全不同：显存占用随音频长度线性增长，因为中间特征与上下文都要保留；解码必须等整段上下文齐备，首包延迟与音频总长挂钩；码本常驻显存且查询维度高，单次查询的带宽开销大。对一路三十秒的语音，这套栈的显存与延迟模型尚可接受；对一路持续数十分钟、且帧每二十毫秒到达一次的实时会话，它既无法增量推进，也无法按会话数做容量规划。</p>\n<p>更具体地说，旧栈的痛点可以拆成三条互相牵制的代价。其一是延迟：首包延迟等于整段编码加整段解码的耗时，帧长再小也无法缩短，因为解码器在等上下文。其二是显存：上下文缓存与中间激活随音频时长增长，并发路数一多，单卡容量迅速见底，容量规划失去可预测性。其三是带宽：大码本的单次最近邻查询要搬运高维码字，查询次数虽少但每次代价高，且无法与逐帧到达的输入节律重叠。三者叠加的结果是，实时通信场景下神经编解码器“质量更好但用不起”，推理栈被迫退回传统编解码器，或者用离线神经编解码器做非实时的后处理。</p>\n\n<h3 id=\"paper-a-streamable-neural-audio-codec-with-2025-sec-2\">二 · 旧栈的量化器结构为什么与流式推进冲突</h3>\n<p>旧栈的核心是单级大码本矢量量化：对每帧特征向量做一次高维最近邻查询，输出一个索引，码本规模决定了重建上限，也决定了查询与存储开销。用公式表示，单级量化为</p>\n<div class=\"formula\">$$ \\hat{x} = Q(x) = \\arg\\min_{c \\in \\mathcal{C}} \\lVert x - c \\rVert_2^2,\\quad |\\mathcal{C}| = N $$</div>\n<p>其中码本 $\\mathcal{C}$ 的容量 $N$ 要足够大才能覆盖特征分布的细节，而查询代价随码字维度与 $N$ 增长。问题不在于单次查询慢，而在于这个结构天然是“整段一次”的：量化器没有帧间状态的概念，解码器也没有增量推进的接口。要把这套结构改造成流式，要么在解码器侧引入因果掩码并缓存历史感受野，要么把量化器拆成可按帧独立执行的多级结构。前者只解决了上下文依赖，后者才解决查询与存储的代价结构——这正是论文选择残差标量-矢量量化的动机。</p>\n<p>从推理系统代价看，单级大码本的显存占用是码本大小乘以码字维度，常驻且与并发无关；但解码器的上下文缓存与音频长度线性相关，是并发容量的真正瓶颈。带宽侧，单次高维最近邻查询要搬运整个码本或其主要部分，查询命中率再高也改变不了单次搬运量大的事实。延迟侧，由于解码必须等整段上下文，首包延迟无法通过增加算力压缩，只能通过缩短音频段来压缩，而这与实时会话的连续性直接冲突。三条代价共同指向一个结论：不改量化器与状态模型，流式场景下的神经编解码器没有可部署的推理栈。</p>\n\n<h3 id=\"paper-a-streamable-neural-audio-codec-with-2025-sec-3\">三 · 残差多级量化的机制：把一次大查询拆成 K 次小查询</h3>\n<p>论文的替代方案是残差标量-矢量量化（RSVQ）：每帧先做标量量化得到粗粒度表示，再对残差做小码本矢量量化，逐级逼近。第一级对特征每个维度独立量化，后续级在小码本上量化前级残差，码本规模远小于单级大码本。其递推形式为</p>\n<div class=\"formula\">$$ \\hat{x}_0 = Q_0(x),\\quad r_1 = x - \\hat{x}_0,\\quad \\hat{x}_1 = \\hat{x}_0 + Q_1(r_1),\\quad \\hat{x} = \\hat{x}_0 + \\sum_{k=1}^{K} Q_k\\!\\left(x - \\hat{x}_{k-1}\\right) $$</div>\n<p>这个结构把“一次高维大码本查询”换成“一次逐维标量量化加 K−1 次小码本矢量查询”。存储上，标量量化器每维只需一组量化电平，后续各级码本容量小，总存储远低于单级大码本；查询上，每次查询的码字维度与候选数都小，单次搬运量下降。代价是串行性：每帧要顺序执行 K 次查询，级数 K 直接线性抬升单帧处理延迟。这就是论文的核心折中——用多级小码本换存储与单次查询开销，代价是单帧延迟随 K 增长。工程判断上，K 的选取不是质量参数，而是延迟预算参数：首包延迟约束先定 K 的上限，再由码本大小在剩余预算内争取重建质量。</p>\n<p>一个具体例子：某路会话帧长固定，单帧编码加解码的预算被 SLO 锁定；若第一级标量量化耗时占比小，后续每级小码本查询各占一份固定耗时，则 K 从三级加到五级，单帧延迟近似线性上升，首包延迟随之上升，而重建质量的边际收益受小码本容量约束递减。此时正确的做法不是继续加级数，而是检查码本容量是否已成为残差逼近的上限——小码本虽降低存储，但残差逐级逼近的重建上限受码本容量约束，高码率场景需增加级数或码本大小，两者都会推高单帧延迟。这个约束在容量规划时必须显式建模，否则会出现“加级数提质量”的直觉性误判。</p>\n\n<h3 id=\"paper-a-streamable-neural-audio-codec-with-2025-sec-4\">四 · 因果卷积与帧间状态缓存：首包延迟与音频总长解耦</h3>\n<p>量化器解决的是查询与存储的代价结构，解码能否按帧增量推进则由状态模型决定。论文的编码器与解码器均为因果卷积，帧间状态缓存保留历史感受野，使解码器每收到一帧码流即可增量重建该帧波形。伪代码思路是：编码器维护一个随帧推进的感受野缓存，每帧输入只与前若干帧的历史状态做卷积，输出当前帧特征并更新缓存；解码器对称地维护反卷积缓存，逐帧输出波形并送入播放缓冲。首包延迟因此取决于单帧编码加单帧解码的耗时，而非音频总长。</p>\n<p>这条机制对推理栈的直接后果是显存模型的变化：流式状态缓存占用固定显存，与并发会话路数线性相关，而不再与音频长度相关。容量规划从“按最长音频估显存”变成“按每路缓存大小乘以并发数估算”，可预测性大幅提升。代价是每路会话必须独立持有编码器与解码器状态，并发路数成为显存的第一约束；同时，因果卷积的感受野长度决定了缓存大小，感受野越长，单路缓存越大，并发上限越低。这是一个与量化级数 K 相互独立的第二个折中维度：K 约束单帧延迟，感受野约束并发容量。</p>\n<p>另一个具体例子：接入节点按会话计并发，每路维护独立的编码器与解码器状态缓存。若把感受野加长以提升重建质量，单路缓存增大，同等显存下的并发路数下降；若为提升并发而缩短感受野，帧间上下文不足，重建质量受损。工程上应把感受野与帧长一起放进延迟预算：帧长决定单帧处理节律，感受野决定缓存与上下文长度，两者共同决定首包延迟与并发容量。播放缓冲深度则决定端到端抖动容忍度与欠载风险——缓冲越深，抖动容忍越好，但端到端延迟越大，这是与编解码器内部延迟无关的第三段预算。</p>\n\n<h3 id=\"paper-a-streamable-neural-audio-codec-with-2025-sec-5\">五 · 旧栈非改不可的工程理由：三条代价无法靠加卡摊薄</h3>\n<p>把旧栈的三条代价放在一起看，会发现它们都无法通过增加算力或带宽来摊薄。首包延迟与音频总长挂钩，加卡只能缩短整段处理时间，改变不了“必须等整段”的结构性等待；显存随音频长度线性增长，加卡只是把同一增长曲线平移，容量规划仍然不可预测；大码本单次查询的搬运量是结构性的，加带宽只是降低单次耗时，改变不了查询次数与串行节律的错配。这正是论文非改不可的理由：问题不在算力不足，而在推理栈的时间模型与显存模型与逐帧到达的输入节律不匹配。</p>\n<p>RSVQ 加因果卷积状态缓存的组合，恰好把这两个模型改造成与流式输入对齐的形态：时间模型从“整段耗时”变为“单帧耗时乘以帧数”，首包只付一帧的代价；显存模型从“随长度增长”变为“随并发增长”，容量规划可按键路缓存估算。代价被转移到了两个新的约束上：多级串行查询使单帧延迟随 K 线性上升，小码本容量限制残差逼近的重建上限。这两个约束是可建模、可预算的，而旧栈的约束是不可摊薄的。对推理工程师而言，这是一个从“不可部署”到“可预算部署”的转变，而不是单纯的质量提升。</p>\n<p>需要强调的是，材料未给出吞吐、延迟与质量的数值结果，因此不能把该工作直接当作低延迟部署的证据引用。可核验的只有机制层面的结论：多级小码本降低码本查询与存储开销，因果卷积与状态缓存使解码按帧增量推进，首包延迟与单帧处理耗时挂钩而非音频总长。部署容量判断必须建立在按每路缓存大小乘以并发数的显存估算、以及按 K 与码本大小裁剪的延迟预算之上，而不是引用未经核验的数值。这也是本卷后续讨论 Blackwell 上 NVFP4/FP8 量化与显存预算时，可以直接迁移的两个建模维度：量化级数对应串行查询延迟，码本与状态缓存对应常驻显存。</p>\n\n<h3 id=\"paper-a-streamable-neural-audio-codec-with-2025-sec-6\">六 · 失败模式：把折中当免费午餐</h3>\n<p>在真实服务里，这套设计的失败模式集中在把折中误读为单向收益。第一种是把多级量化当作纯质量提升手段，不断加级数，忽视串行查询对单帧延迟的线性抬升，结果首包延迟击穿 SLO，而质量边际收益已被小码本容量封顶。第二种是按离线编解码器的显存模型估算容量，忽略流式状态缓存随并发路数线性增长，上线后并发一高就出现显存不足，且无法通过缩短音频长度缓解。第三种是在缺乏数值结果的情况下直接引用该工作作为低延迟部署的证据，把机制上的可行性当成实测的达标，容量规划失去数据支撑。</p>\n<p>避免这三类失败的关键，是把 K、码本大小、感受野、帧长、播放缓冲深度五个参数放进同一个预算框架：K 与码本大小约束单帧延迟与重建上限，感受野与帧长约束单路缓存与单帧节律，播放缓冲深度约束端到端抖动与欠载风险。任何一个参数的单向优化都会在另一个维度上付出代价。工程判断应落在“先定 SLO 的首包延迟上限，再反推 K 的上限，再在剩余预算内选码本大小与感受野”的顺序上，而不是先追质量再压延迟。这条顺序也是把该论文的量化器结构迁移到 Blackwell 部署时的起点：多级小码本的存储节省可以换成更大的并发容量或更高的精度格式，但串行查询的延迟代价必须先在预算里扣除。</p>\n<h3 id=\"paper-a-streamable-neural-audio-codec-with-2025-sec-7\">七 · 请求形态：帧到达节奏与不可攒批约束</h3>\n<p>实时通信的请求不是“一段音频”而是一条持续到达的帧序列。论文的推理管线把输入按固定帧长切分，帧到达即触发编码，明确不允许跨帧攒批。这一条约束直接决定了负载形态：批大小在单路会话内恒为 1，任何提升吞吐的手段都必须从“多路并发”而非“单路攒批”里找。对 Blackwell 部署而言，这意味着 SM 上的 MMA 利用率天然偏低——单帧张量的维度远小于 tcgen05 的推荐 tile，NVFP4/FP8 的算力优势在 batch=1 的编码器前段很难兑现，真正的瓶颈落在码本查询与状态缓存的访存上。</p>\n<p>可核查的测量口径必须把“到达”与“处理”分开计时：在帧入口打时间戳 t_arrive，在编码器输出码流处打 t_enc，在解码器输出重建帧处打 t_dec，首包延迟定义为 t_dec(第 0 帧) − t_arrive(第 0 帧)，稳态单帧处理耗时定义为相邻两帧 t_dec 的差值序列。只报端到端平均延迟会把首帧的冷启动成本摊薄，掩盖真实 SLO 风险。抖动容忍度由播放缓冲深度刻画：设帧长为 L、缓冲深度为 D 帧，则端到端可容忍的处理抖动上限为 D·L 减去网络单程时延，欠载次数即缓冲被读空的事件计数，这是比平均延迟更硬的 SLO 指标。</p>\n<p>具体例子：一路 48 kHz 语音按固定帧长切分，编码器因果卷积逐帧推进并下采样到固定帧率。若某帧因调度抖动晚到 Δ，解码器仍按序消费，缓冲深度 D 吸收 Δ；一旦 Δ 超过 D·L，播放端出现欠载，主观体验从“延迟略高”直接跌为“断续”。因此容量规划的第一问不是“能跑多少路”，而是“在给定 D 下能容忍多大的单帧耗时上尾”。</p>\n\n<h3 id=\"paper-a-streamable-neural-audio-codec-with-2025-sec-8\">八 · 并发：状态缓存乘以路数的显存账</h3>\n<p>每路会话维护独立的编码器与解码器状态缓存，显存随并发线性增长。这是该方案与离线编解码器最本质的容量差异：离线模型按整段音频分配激活，长度越长越贵；流式方案按帧间感受野保留固定缓存，长度无关但与路数成正比。容量估算的口径因此变成</p>\n<div class=\"formula\">$$ M_{\\text{total}} = M_{\\text{codebook}} + N_{\\text{sess}} \\times \\left( S_{\\text{enc}} + S_{\\text{dec}} \\right) + M_{\\text{runtime}} $$</div>\n<p>其中 S_enc、S_dec 为单路编解码器状态缓存字节数，由因果卷积各层感受野与通道宽度决定，N_sess 为并发会话数，M_codebook 为各级码本常驻显存。M_codebook 因多级小码本设计而远小于单级大码本，但它是与路数无关的固定项；随着 N_sess 上升，状态缓存项成为主导，这正是“按离线显存模型估容量”会失准的地方——离线模型里没有这一项。</p>\n<p>工程上的直接后果是并发上限由显存而非算力决定。B200 的 HBM 容量给了较大的 N_sess 空间，但每路缓存必须真实驻留、不能被换出，否则帧间状态断裂会直接破坏重建连续性。可核查口径：在稳定并发 N 下连续跑足够长的帧数，采样 nvidia-smi 的显存占用并核对是否等于上述公式的预测值；同时记录每路缓存的分配地址是否复用（避免碎片导致的隐性增长）。另一个易被忽略的代价是功耗——常驻缓存使 SM 无法深度休眠，长时空闲会话仍占用显存与漏电，容量规划应把“在线但静默”的会话计入 N_sess。</p>\n\n<h3 id=\"paper-a-streamable-neural-audio-codec-with-2025-sec-9\">九 · 单帧延迟：K 次串行查询的线性抬升</h3>\n<p>多级残差量化的每帧计算是串行的：第一级标量量化对每个维度独立量化，随后每一级在小码本上对前级残差做最近邻查询，逐级累加。设级数为 K，则单帧至少包含 K 次串行查询，第 k 级必须等第 k−1 级的残差就绪。单帧处理耗时因此近似为</p>\n<div class=\"formula\">$$ T_{\\text{frame}} \\approx T_{\\text{conv}} + \\sum_{k=0}^{K} T_{\\text{query}}(k) + T_{\\text{deconv}} $$</div>\n<p>级数增加线性抬升 T_frame，而首包延迟等于首帧的 T_frame（加冷启动），所以 K 是首包延迟与重建质量的直接折中旋钮。这与“多级量化只是质量提升手段”的直觉相反：在流式 SLO 下，K 首先是延迟预算的消耗项。可核查口径是把 T_query(k) 按级拆开计时，观察是否真的随 k 线性增长——若某级码本过大导致缓存未命中，该项会显著偏离线性，此时应优先裁剪该级码本而非整体降 K。</p>\n<p>具体例子：解码器每收到一帧码流即调用因果反卷积，利用缓存状态增量重建该帧波形并送入播放缓冲。若 K 从较小值提高到较大值以改善高码率下的重建，单帧耗时随之上升，首包延迟同步上升；在固定播放缓冲深度下，这会把原本安全的抖动余量吃掉。工程判断是：把 K 与码本大小一起纳入延迟预算求解，而不是先定质量目标再倒推延迟。Blackwell 上可用的手段是把各级查询融合进一次小规模 MMA 或利用 TMEM 暂存中间残差以减少往返，但串行依赖本身不可消除，只能压缩每级的常数项。</p>\n\n<h3 id=\"paper-a-streamable-neural-audio-codec-with-2025-sec-10\">十 · 长尾：上尾而非均值决定 SLO</h3>\n<p>流式编解码的 SLO 由尾延迟定义。设单帧耗时分布为 T，SLO 要求第 p 分位（如 p99）不超过预算 B，则容量规划的条件是</p>\n<div class=\"formula\">$$ \\Pr\\{T_{\\text{frame}} &gt; B\\} \\le 1-p $$</div>\n<p>均值达标毫无意义：一帧超预算就产生一次缓冲欠载，而欠载在听感上是离散事件，不因其余帧很快而被平均掉。长尾来源有三类，需分别测量：其一是码本查询的缓存行为，小码本常驻显存但查询索引分布不均，热点维度与非热点维度的访存延迟不同；其二是多路并发下的 SM 争用，N_sess 上升时单路 T_frame 的上尾被拉长，因为状态缓存的读写与其他会话竞争同一 HBM 带宽；其三是调度抖动，帧到达时刻本身不均匀，t_arrive 的间隔分布应与 t_dec 的间隔分布对比，二者之差才是系统引入的抖动。</p>\n<p>可核查口径建议：按会话记录每帧的 (t_arrive, t_enc, t_dec) 三元组，输出 T_frame 的 p50/p99/max 与欠载事件计数，并在不同 N_sess 下重复，得到“上尾随并发增长”的曲线。这条曲线才是容量规划的依据。具体例子：两路会话同时进入活跃语音段时，HBM 带宽被两份状态缓存读写分摊，单路 p99 可能明显高于单路独跑时的 p99；若只看单路基准测试的均值，上线后会低估所需缓冲深度。Blackwell 的 NVLink 5 与 NIXL 在此处的价值不是提升单帧算力，而是让编码与解码可分离部署、把首帧处理与后续帧流水重叠，从而压缩 t_dec 的等待段——但这要求跨节点传输的码流按帧打包、逐帧拉取，传输延迟本身进入抖动预算。</p>\n\n<h3 id=\"paper-a-streamable-neural-audio-codec-with-2025-sec-11\">十一 · 方案反过来限制负载：码本容量与码率的闭环</h3>\n<p>负载塑造方案，方案也反向约束负载。小码本容量约束残差逐级逼近的重建上限，高码率场景需增加级数或码本大小，二者都推高单帧延迟；而单帧延迟的上尾又反过来限制了可支持的并发与可容忍的抖动。这是一个闭环：质量目标 → K 与码本大小 → T_frame → 并发上限与缓冲深度 → 可接受的会话形态。工程上应把这个闭环写成约束求解，而非逐项调参。</p>\n<p>具体机制上，码流按帧打包发送、接收端逐帧拉取解码，意味着码率是每帧索引位数的函数：第一级标量量化每维独立索引，后续各级为小码本索引，总位数随 K 线性增长。提高码率最直接的方式是加级，但这正是延迟最贵的方向。可核查口径是记录每帧码流的实际字节数与各级索引的分布熵——若某级索引熵接近码本上限，说明该级已饱和，继续加级收益递减而延迟照涨；若熵很低，说明码本对该路语音过设计，可裁剪以省查询开销。</p>\n<p>具体例子：一路高码率语音使某级矢量量化索引频繁触及码本边界，重建残差无法继续收敛，运维侧看到的是质量投诉而非延迟告警；此时若简单加 K，首包延迟与 p99 同步恶化，可能触发欠载。正确判断是先看各级索引熵与残差能量分布，确认瓶颈在哪一级，再决定是扩该级码本还是加级。Blackwell 部署中，码本常驻显存可放在高带宽区域，但码本扩大同时抬高 M_codebook 这一与路数无关的固定项，在低并发场景反而摊薄了单位路数的显存效率——容量规划需按目标并发档位选择码本规模，而不是取最大。</p>\n\n<h3 id=\"paper-a-streamable-neural-audio-codec-with-2025-sec-12\">十二 · 测量口径清单与不可核验项</h3>\n<p>把上述讨论收敛成一张可执行的测量表，避免用离线指标冒充流式指标。下表列出每项的口径与它约束的系统代价。</p>\n<table class=\"mini\"><thead><tr><th>指标</th><th>测量口径</th><th>约束的代价</th></tr></thead><tbody>\n<tr><td>首包延迟</td><td>t_dec(第0帧) − t_arrive(第0帧)，含冷启动</td><td>单帧 T_frame 与 K</td></tr>\n<tr><td>单帧耗时分布</td><td>相邻 t_dec 差值序列的 p50/p99/max</td><td>上尾决定缓冲深度</td></tr>\n<tr><td>欠载次数</td><td>播放缓冲被读空的事件计数</td><td>抖动容忍度与 SLO</td></tr>\n<tr><td>每路状态缓存</td><td>S_enc + S_dec 实测字节数</td><td>并发上限（显存线性）</td></tr>\n<tr><td>码本常驻显存</td><td>M_codebook 固定项</td><td>低并发下的显存效率</td></tr>\n<tr><td>各级查询耗时</td><td>T_query(k) 按级拆分</td><td>K 的线性抬升是否成立</td></tr>\n<tr><td>各级索引熵</td><td>每帧码流位数与索引分布熵</td><td>码本是否饱和/过设计</td></tr>\n<tr><td>到达间隔分布</td><td>t_arrive 间隔 vs t_dec 间隔</td><td>系统引入的抖动</td></tr>\n</tbody></table>\n<p>必须明确的是，材料未给出吞吐、延迟与质量的数值结果，因此上述口径只能给出测量方法与约束关系，不能给出可引用的容量数字。任何把该工作当作“低延迟部署已证”的引用都缺乏数据支撑；可核验的只有机制层面的因果链：帧到达即编码、K 次串行查询、状态缓存随路数线性增长、首包延迟与音频总长解耦。工程判断应落在“先测上尾与欠载，再定 K 与并发”，而不是先假定一个延迟预算再反推架构。</p>\n\n<h3 id=\"paper-a-streamable-neural-audio-codec-with-2025-sec-13\">十三 · 帧到达节奏如何反向约束量化级数与并发上限</h3>\n<p>这个方案对负载的第一条硬约束是“不允许跨帧攒批”：帧一到就触发编码，批大小恒为 1（每路会话），因此吞吐不由批调度决定，而由单帧串行路径决定。单帧代价可写成 <span class=\"formula\">$$T_{\\text{frame}} = T_{\\text{enc}} + K \\cdot T_{\\text{nn}} + T_{\\text{dec}}$$</span>，其中 <span class=\"formula\">$$T_{\\text{nn}}$$</span> 是单级小码本最近邻查询耗时，K 为残差级数。首包延迟约等于 <span class=\"formula\">$$T_{\\text{frame}}$$</span> 加播放缓冲预填深度，与音频总长无关——这正是它相对离线编解码器的边界所在，也是它失效的起点：K 一增加，延迟线性抬升，SLO 预算被逐级吃掉。</p>\n<p>并发侧则是另一条线性关系。每路会话持有独立的编码器与解码器帧间状态缓存，显存占用近似 <span class=\"formula\">$$M \\approx N_{\\text{sess}} \\cdot (S_{\\text{enc}} + S_{\\text{dec}}) + M_{\\text{codebook}}$$</span>。码本常驻且与并发无关，状态缓存却随路数线性增长，所以容量规划不能沿用离线编解码器“显存随音频长度增长”的模型，而应把并发数当作第一变量。可核查的测量口径应固定为四项：单帧编码耗时、单帧解码耗时、首包延迟（首帧解码完成时刻减帧到达时刻）、播放缓冲欠载次数；另加码本查询命中率与每路状态缓存字节数，用于反推并发上限。</p>\n<table class=\"mini\"><thead><tr><th>负载变量</th><th>对方案的塑造</th><th>方案对负载的反向限制</th></tr></thead><tbody><tr><td>帧长</td><td>决定单帧特征维度与解码粒度</td><td>帧长过短则帧率上升，串行查询次数同比增加</td></tr><tr><td>量化级数 K</td><td>决定重建上限与码率</td><td>K 抬升单帧延迟，压缩可接纳并发与抖动余量</td></tr><tr><td>并发路数</td><td>决定状态缓存总量</td><td>显存上限反过来封顶同时在线的会话数</td></tr><tr><td>播放缓冲深度</td><td>吸收到达抖动</td><td>缓冲越深，端到端延迟预算越紧，K 越受限</td></tr></tbody></table>\n<p>长尾来自两个方向：一是多级量化的串行依赖使单帧延迟分布右偏，任何一级查询遇到码本未命中或缓存换入都会拉长该帧；二是并发突增时状态缓存争用显存，触发换出后单帧耗时跃升。工程判断是：在缺乏该工作吞吐、延迟与质量数值结果的前提下，不应把它当作低延迟部署的证据引用；可行做法是先按 K 与码本大小做延迟预算裁剪，再用每路缓存字节数乘并发数反推显存上限，把“级数换质量”的决策锁在 SLO 余量之内，而不是把多级量化当成纯质量提升手段。</p>\n<h3 id=\"paper-a-streamable-neural-audio-codec-with-2025-sec-14\">十四 · 从码本查表到 Tensor Core：RSVQ 的算子分解</h3>\n<p>把论文的量化公式拆到 kernel 粒度，一帧特征在 Blackwell 上的执行路径可以分成四段：第一级标量量化是逐维度的乘加与舍入，本质是一次 <span>clamp(round(x/s))</span> 的逐元素操作，属于纯 elementwise，带宽受限而非算力受限；后续 K−1 级矢量量化每级要做一次最近邻查询，即对残差向量与小码本中每个码字求距离并取最小，这是 <span>N×C×D</span> 的乘加规约，属于 GEMM 形状的算子；每级查询得到索引后要从码本中 gather 出码字并与前级重建相加，这是一次残差累加；最后解码器的因果反卷积把量化后的特征还原为波形，是带状态的卷积。四段算子的性质完全不同：第一段吃显存带宽，第二段吃 Tensor Core 的规约吞吐，第三段吃随机访存与 L2 命中，第四段吃卷积吞吐并受帧间状态缓存的读写约束。Blackwell 部署的第一个工程判断就是把这四段分别映射到合适的执行单元，而不是把整帧当作一个黑盒 kernel 丢给框架自动调度。</p>\n<p>最近邻查询的代价可以写成：</p>\n<div class=\"formula\">$$ d_{k,c} = \\lVert r_k - C_k[c] \\rVert_2^2 = \\lVert r_k \\rVert_2^2 - 2\\, r_k^{\\top} C_k[c] + \\lVert C_k[c] \\rVert_2^2,\\quad i_k = \\arg\\min_c d_{k,c} $$</div>\n<p>逐项解释：<span>r_k</span> 是第 k 级输入的残差向量，<span>C_k</span> 是第 k 级小码本，<span>c</span> 遍历码本条目。展开后第一项与第三项可以预计算——<span>\\(\\lVert C_k[c]\\rVert_2^2\\)</span> 在码本加载时一次算好常驻，<span>\\(\\lVert r_k\\rVert_2^2\\)</span> 每帧只算一次；真正每帧随码字变化的是中间的交叉项 <span>\\(r_k^{\\top} C_k[c]\\)</span>，它是一个 <span>1×D</span> 乘 <span>D×C</span> 的向量-矩阵乘。于是\"求最近邻\"被改写成\"做一次小 GEMV 再取 argmin\"，这正是 Tensor Core 能接手的形态。代价在于：argmin 本身不是矩阵运算，需要在 GEMV 结果上做一次跨 C 维的规约比较，这一步在 SM 内用 warp shuffle 完成，其延迟与 C 的对数成正比；C 越大，规约树越深，单级查询的尾延迟越长。这就是小码本设计的硬件含义——它不只是省显存，更是把 argmin 规约树的深度压在可控范围内。</p>\n\n<h3 id=\"paper-a-streamable-neural-audio-codec-with-2025-sec-15\">十五 · 数据类型选择：FP16、BF16、FP8 与 NVFP4 在编解码器里的分工</h3>\n<p>编解码器的数值需求并不均一。编码器前端处理的是归一化后的波形采样，动态范围窄但要求相位保真；量化端的残差逐级递减，后几级的残差幅度已经很小，对量化误差极度敏感；解码器输出直接进播放缓冲，任何数值噪声都会被听感放大。因此不能用一个精度档位贯穿全链路。Blackwell 的第五代 Tensor Core 提供了 FP16、BF16、FP8（E4M3/E5M2）与 NVFP4 四档乘加精度，配合不同的累加器宽度，工程上的分工是：波形前端与解码器末段用 FP16 保相位；码本距离计算与残差投影这类规约型算子用 BF16 或 FP8 换吞吐；NVFP4 只在码本条目存储与超大批量离线校准场景有意义，因为它的块缩放（每 16 元素一个 E4M3 缩放因子）能压住小幅度残差的量化噪声，但逐帧解码路径上引入块缩放的解包开销往往得不偿失。</p>\n<p>误差传播的定量关系需要写清楚。设第 k 级矢量量化的量化误差为 <span>e_k</span>，则总重建误差是各级误差的叠加：</p>\n<div class=\"formula\">$$ x - \\hat{x} = \\sum_{k=1}^{K} e_k,\\qquad \\mathbb{E}\\lVert e_k \\rVert_2^2 \\approx \\frac{\\Delta_k^2}{12}\\, D,\\quad \\Delta_k \\propto 2^{-b_k} $$</div>\n<p>这里 <span>\\(\\Delta_k\\)</span> 是第 k 级的量化步长，<span>b_k</span> 是该级的有效位宽，<span>D</span> 是特征维度。关键结论是：误差按级叠加而非抵消，所以后几级的精度档位不能随意下调——如果前级已经把残差压到很小，后级用 FP8 引入的相对误差会直接成为总误差的主导项。工程上的做法是让级数 K 与精度档位联动：级数少时每级必须用高精度把残差压到位，级数多时后级残差幅度小、可以容忍更低位宽，但前提是码本距离计算仍在 FP16/BF16 累加，避免 argmin 被低精度距离值翻转。argmin 翻转是这里最隐蔽的失败模式：两个码字的距离在 FP8 下算出来相等或次序颠倒，选错码字带来的误差远大于该级本身的量化误差，且不可通过增加级数补救。</p>\n<p>累加精度是另一条独立约束。Blackwell Tensor Core 的 FP8 乘加可以在 FP32 累加器上完成，这对 <span>\\(r_k^{\\top}C_k[c]\\)</span> 这类规约至关重要：D 维的点积若用 FP16 累加，累加器溢出与舍入会随 D 增长而累积，而 FP32 累加把这项误差压到可忽略。代价是累加器占用的寄存器与 TMEM 容量翻倍，直接限制了同时驻留的查询批次大小——在每路会话独立状态缓存的流式场景下，这个容量约束会转化为并发路数的上限。</p>\n\n<h3 id=\"paper-a-streamable-neural-audio-codec-with-2025-sec-16\">十六 · Blackwell 特性映射：tcgen05、TMEM 与 2-SM MMA</h3>\n<p>tcgen05 是 Blackwell 上第五代 Tensor Core 的指令族，它把矩阵乘的累加器从寄存器文件搬到 Tensor Memory（TMEM）——一块与 SM 紧邻、专供 Tensor Core 读写的片上存储。对 RSVQ 的意义在于：最近邻查询的 GEMV 结果不再需要写回寄存器再做 argmin，而是留在 TMEM 中由后续的规约指令直接消费，省掉一次寄存器往返。TMEM 的容量是硬约束，它决定了单个 SM 上能同时挂多少路查询的中间结果；在流式解码中，每路会话的 K 级查询是串行的，但不同会话之间可以并行，TMEM 容量因此直接换算成每 SM 的并发会话数上限。这是把\"显存随并发线性增长\"这一事实落到片上资源的具体路径：状态缓存占 HBM，TMEM 占的是查询中间态，两者共同构成并发天花板。</p>\n<p>2-SM MMA 让两个 SM 协作完成一次矩阵乘，共享操作数并合并累加。对码本距离计算这类 <span>1×D</span> 乘 <span>D×C</span> 的小形状算子，单 SM 往往喂不满 Tensor Core 的吞吐，2-SM 协作把有效矩阵高度翻倍，提升了小形状下的利用率。但代价是同步开销：两个 SM 必须在 MMA 前后对齐，这在逐帧、低延迟的流式路径上会引入固定的跨 SM 同步延迟，帧长越短、单帧计算越薄，这项开销占比越高。工程判断是：当每帧查询的码本规模足够大（C 与 D 的乘积超过单 SM 的经济阈值）时启用 2-SM，否则单 SM 的 GEMV 加 warp 规约反而延迟更低。这与论文里\"级数增加线性抬升单帧延迟\"的结论是同一枚硬币的两面——并行度换吞吐，但换不来更短的首包。</p>\n<p>把三段映射写成伪代码思路：</p>\n<div class=\"formula\">$$ \\text{for } k \\text{ in } 1..K:\\ \\ \\text{TMEM} \\leftarrow \\text{tcgen05.GEMV}(r_k, C_k);\\ \\ i_k \\leftarrow \\text{argmin}_{\\text{TMEM}};\\ \\ r_{k+1} \\leftarrow r_k - \\text{gather}(C_k, i_k) $$</div>\n<p>循环体内的三次操作分别落在 Tensor Core、SM 内规约单元与随机访存单元上，K 次串行意味着这三段流水无法跨级重叠——这是 RSVQ 在 Blackwell 上最本质的延迟来源。可以做的优化是把不同会话的第 k 级查询拼成批，让 Tensor Core 在会话维度上获得并行度，用吞吐换单路延迟的隐藏；但这要求框架具备跨会话的 kernel 融合能力，TensorRT-LLM 的 plugin 与 Triton 的自定义 kernel 是两条可行路径，前者适合固定形状的码本查询，后者适合级数与码本大小随档位变化的场景。</p>\n\n<h3 id=\"paper-a-streamable-neural-audio-codec-with-2025-sec-17\">十七 · 单帧延迟的分解与精度档位的代价核算</h3>\n<p>把首包延迟写成可核算的形式：</p>\n<div class=\"formula\">$$ T_{\\text{first}} = T_{\\text{enc}} + \\sum_{k=1}^{K}\\left( T_{\\text{gemv},k} + T_{\\text{argmin},k} + T_{\\text{gather},k} \\right) + T_{\\text{dec}} + T_{\\text{sync}} $$</div>\n<p>逐项解释：<span>\\(T_{\\text{enc}}\\)</span> 是因果卷积编码一帧的耗时，受帧长与感受野约束；求和项是 K 级量化的串行开销，其中 <span>\\(T_{\\text{gemv},k}\\)</span> 随码本大小 C 与维度 D 增长、<span>\\(T_{\\text{argmin},k}\\)</span> 随 log C 增长、<span>\\(T_{\\text{gather},k}\\)</span> 受码本是否常驻 L2 影响；<span>\\(T_{\\text{dec}}\\)</span> 是因果反卷积重建一帧的耗时；<span>\\(T_{\\text{sync}}\\)</span> 是 kernel 启动与跨 SM 同步的固定开销。这个式子把论文中\"级数增加线性抬升单帧延迟\"的定性判断落到了具体项上：K 出现在求和上限，每一项都随 K 线性累加，而 <span>\\(T_{\\text{sync}}\\)</span> 是每帧固定付出的底噪——帧越短，底噪占比越高，这就是为什么极低延迟场景下不能无限缩短帧长。</p>\n<p>精度档位对这项延迟的影响是双向的。降精度（FP16→FP8）提升 Tensor Core 吞吐，压缩 <span>\\(T_{\\text{gemv},k}\\)</span>；但 FP8 的码本需要解包缩放因子，增加 <span>\\(T_{\\text{gather},k}\\)</span> 的访存指令数，且 argmin 在低精度距离上更易翻转，迫使工程上保留 FP32 累加与更高精度的比较，抵消部分收益。NVFP4 的块缩放把这两难推到极致：存储密度最高，但每 16 元素一个缩放因子的解包在逐帧路径上是纯开销。因此在流式编解码器里，精度档位的选择不应按\"越低越省\"的直觉走，而应按 <span>\\(T_{\\text{gemv},k}\\)</span> 与 <span>\\(T_{\\text{gather},k}\\)</span> 的相对占比来定：码本小、查询密集时降精度收益明显；码本大、gather 主导时降精度反而拖慢。</p>\n<p>具体例子：一路 48 kHz 语音按固定帧长切分，编码器因果卷积下采样到固定帧率，每帧特征经第一级标量量化后残差进入若干级小码本矢量量化。若把级数从少增到多，单帧查询次数成比例上升，首包延迟随之抬升，而重建质量的上限受各级码本容量约束——这正是论文所说\"级数与码本大小按延迟预算裁剪\"的工程含义。在 Blackwell 上，裁剪的依据就是上式各项的实测占比，而不是离线编解码器时代的\"码本越大越好\"。</p>\n\n<h3 id=\"paper-a-streamable-neural-audio-codec-with-2025-sec-18\">十八 · 状态缓存、显存与并发：精度选择如何反噬容量</h3>\n<p>流式解码的显存模型与离线完全不同。离线编解码器按整段音频分配激活，显存随音频长度线性增长；流式路径下激活被压到单帧，但每路会话必须常驻一份帧间状态缓存（因果卷积的历史感受野）与一份码本副本。容量估算因此是：</p>\n<div class=\"formula\">$$ M_{\\text{total}} \\approx N_{\\text{sess}} \\times \\left( S_{\\text{state}} + S_{\\text{codebook}} \\right) + M_{\\text{weights}} $$</div>\n<p>逐项解释：<span>\\(N_{\\text{sess}}\\)</span> 是并发会话路数，<span>\\(S_{\\text{state}}\\)</span> 是每路状态缓存大小（由感受野与特征维度决定），<span>\\(S_{\\text{codebook}}\\)</span> 是各级码本的常驻副本，<span>\\(M_{\\text{weights}}\\)</span> 是编解码器权重。关键点是码本副本是否每路一份：若框架把码本作为共享只读数据放在 L2 或常量内存，<span>\\(S_{\\text{codebook}}\\)</span> 就不进入每路预算；若为降低 gather 延迟而把码本复制到每路的片上或近端存储，它就成为并发路数的直接乘数。精度档位在这里反噬容量：码本用 FP16 存储时每路副本是 FP8 的两倍，而 NVFP4 虽然存储最省，但解包后的中间态反而占用更多寄存器与 TMEM。这就是\"降精度省显存\"在流式场景下不总成立的原因——省的是权重与码本，费的是中间态与解包开销。</p>\n<p>工程判断落在监控指标上：首包延迟、单帧编解码耗时、码本查询命中率、播放缓冲欠载次数。命中率低说明码本没有常驻近端存储，gather 在打 HBM；欠载次数上升说明单帧处理耗时超过了播放缓冲的抖动容忍度，此时要么加级数换质量、要么降级数保延迟。这两个指标共同划定了精度档位与级数的可行域，而 Blackwell 的 TMEM 容量与 L2 带宽是这条可行域的物理边界。</p>\n<p>最后落在具体机制上：RSVQ 的 K 级串行查询在 Blackwell 上的最优映射不是把每级都做成独立 kernel，而是把同一会话的 K 级查询与不同会话的同级查询在 TMEM 中拼批，用 tcgen05 的 GEMV 加 SM 内 argmin 规约完成单级闭环，再把 gather 与残差累加融合进下一级的输入准备。这条路径的收益上限由 TMEM 容量与码本驻留层级决定，其延迟下限则由 K 次串行规约树的深度决定——级数与码本大小在延迟预算内的裁剪，本质是在这两个硬件常数之间找可行点。</p>\n\n<h3 id=\"paper-a-streamable-neural-audio-codec-with-2025-sec-19\">十九 · 权重账本：码本常驻与分级存储</h3>\n<p>在 Blackwell 上给这个流式编解码器做显存预算，第一笔账不是权重矩阵，而是码本。RSVQ 的结构决定了码本不是一张大表，而是 K+1 张小表：第 0 级标量量化器每个维度一套独立阈值与重建电平，后续 K 级各持一个小码本。设第 k 级码本含 \\(C_k\\) 个码字、每码字维度为 \\(d\\)，则该级码本显存为 \\(C_k d b_q\\) 字节，\\(b_q\\) 为码字元素位宽（FP8 为 1 字节、FP16 为 2 字节）。总码本账本：</p>\n<div class=\"formula\">$$ M_{\\text{cb}} = \\underbrace{d\\,b_s}_{\\text{标量级}} + \\sum_{k=1}^{K} C_k\\, d\\, b_q $$</div>\n<p>关键判断是：码本是只读的、跨会话共享的、且被每帧每级反复查询。因此它应当常驻 HBM 并尽量驻留在 L2，而不是按会话复制。Blackwell 的 L2 容量相对单卡 HBM 小一个量级以上，K 级小码本若总量能塞进 L2，则每帧 K 次最近邻查询的访存代价从 HBM 往返降为片上命中——这是 RSVQ 相对单级大码本最直接的带宽收益。工程上把码本按级做常量内存/只读缓存标注，并把标量级的阈值表与重建电平表合并为一次向量化加载，可把每帧的码本访存压到 K 次合并访问。代价面：码本常驻占用的是每卡固定显存，与并发无关，但它挤占的是 KV 与激活的可用额度，容量规划时必须先扣掉这笔。</p>\n<p>举例：若某级码本 \\(C_k=1024\\)、\\(d=8\\)、FP16 存储，则该级 16 KiB；K=4 级加上标量级，码本总量在百 KiB 量级，单卡上完全可常驻并被 L2 覆盖。这说明该结构的显存矛盾不在权重侧，而在状态缓存侧——这正是下一节要算的账。</p>\n\n<h3 id=\"paper-a-streamable-neural-audio-codec-with-2025-sec-20\">二十 · 状态缓存账本：随并发线性增长的那一项</h3>\n<p>因果卷积编解码器的“KV cache”不是注意力 KV，而是帧间感受野状态：编码器每层保留历史输入窗口，解码器每层保留历史中间激活，逐帧推进时只更新窗口尾部。设编码器有 \\(L_e\\) 层、解码器 \\(L_d\\) 层，第 l 层状态张量形状为 \\(S_l\\)（通道数 × 感受野长度），元素位宽 \\(b_a\\)，则单路会话状态缓存：</p>\n<div class=\"formula\">$$ M_{\\text{state}} = b_a \\left( \\sum_{l=1}^{L_e} |S_l^{(e)}| + \\sum_{l=1}^{L_d} |S_l^{(d)}| \\right),\\qquad M_{\\text{total}} = M_{\\text{state}} \\cdot N_{\\text{sess}} $$</div>\n<p>这里必须纠正一个常见误判：把离线编解码器的显存模型套到流式部署上，会得出“显存与音频长度无关”的乐观结论，却漏掉 \\(N_{\\text{sess}}\\) 这一乘数。实时通信的并发按会话计，每路独立维护编解码器状态，显存随并发线性增长，而 HBM 容量是固定的。Blackwell 单卡 HBM3e 容量给定了上限 \\(M_{\\text{HBM}}\\)，可容纳会话数的硬上界即：</p>\n<div class=\"formula\">$$ N_{\\max} = \\left\\lfloor \\frac{M_{\\text{HBM}} - M_{\\text{cb}} - M_{\\text{w}} - M_{\\text{act}}^{\\text{peak}}}{M_{\\text{state}}} \\right\\rfloor $$</div>\n<p>其中 \\(M_w\\) 为编解码器卷积权重，\\(M_{\\text{act}}^{\\text{peak}}\\) 为单帧前向的峰值激活。注意分母是单路状态而非单帧激活——这是流式与离线的分水岭。代价面：状态缓存是长驻显存，不随帧释放；它决定了单卡并发上限，进而决定单位算力的服务容量。若 \\(M_{\\text{state}}\\) 偏大，即便算力充裕，卡也会先被显存打满，表现为并发上不去而非 GPU 利用率低。</p>\n<p>举例：设单路状态缓存为若干 MiB 量级（由层数、通道与感受野决定），在数十 GiB 级 HBM 上，并发上限由除法直接给出；此时若盲目按“显存与音频长度无关”估算，会把并发高估数倍，上线后触发 OOM 或被迫降级。可复算的做法是：先固定帧长与感受野，实测单路 \\(M_{\\text{state}}\\)，再用上式反解并发上限，并把播放缓冲深度作为抖动容忍度的独立参数单列。</p>\n\n<h3 id=\"paper-a-streamable-neural-audio-codec-with-2025-sec-21\">二十一 · 分页、压缩、复用、卸载：四类手段的适用边界</h3>\n<p>状态缓存的分页与注意力 KV 的分页逻辑同源但语义不同：注意力按 token 追加、按块分配；因果卷积状态是定长滑动窗口，天然适合“环形缓冲 + 固定槽位”。实现上给每路会话预分配一个定长状态槽，槽内按层切分，帧推进时只覆写窗口尾部，避免动态分配带来的碎片与分配器延迟。分页在这里的价值不是省显存，而是把“按会话分配”变成“按槽位池分配”，使并发上限可被池大小硬约束，防止请求突增时显存无界增长。</p>\n<ul>\n<li><b>压缩</b>：状态缓存以 FP8 存储可把 \\(M_{\\text{state}}\\) 减半，代价是帧间累积误差——因果卷积状态会被后续帧反复读取，量化误差沿时间累积，需在感受野尾部做周期性重算校准。</li>\n<li><b>复用</b>：码本跨会话共享是零成本复用；状态缓存不可复用（每路语音内容不同）。真正可复用的是编解码器权重与常量表，应做成进程级单例而非每会话副本。</li>\n<li><b>卸载</b>：把长时间静默会话的状态槽换出到主机内存，槽位回收给活跃会话。判据是会话活跃度而非音频长度；换出/换入的 PCIe 往返延迟必须小于播放缓冲深度，否则换入即欠载。</li>\n</ul>\n<p>代价面各不相同：压缩省显存但引入重算算力；复用省显存但要求权重只读共享；卸载省显存但把显存压力转成主机带宽与尾延迟。四类手段不能叠加滥用——对一个每帧都要全量读取的状态缓存做卸载，等于把 HBM 带宽瓶颈换成 PCIe 带宽瓶颈，通常更糟。</p>\n\n<h3 id=\"paper-a-streamable-neural-audio-codec-with-2025-sec-22\">二十二 · 带宽瓶颈定位：每帧的字节账</h3>\n<p>流式编解码器每帧的耗时由算力与带宽共同决定，需先判断谁是瓶颈。每帧需搬运的字节包括：码本查询（K 级，若 L2 命中则不计 HBM）、状态缓存读写（每层读旧窗口、写新尾部）、激活中间结果。单帧 HBM 流量近似：</p>\n<div class=\"formula\">$$ B_{\\text{frame}} \\approx 2\\,b_a\\sum_{l}\\left(|S_l^{\\text{rd}}| + |S_l^{\\text{wr}}|\\right) + B_{\\text{act}} + B_{\\text{cb}}^{\\text{miss}} $$</div>\n<p>判据是算术强度：单帧浮点运算量除以 \\(B_{\\text{frame}}\\)。因果卷积的感受野越长、通道越宽，状态读写字节越大而运算增长相对温和，算术强度下降，系统滑向带宽受限。此时提升算力无效，必须减少状态字节——降位宽、缩感受野、或把状态驻留片上。Blackwell 的 HBM3e 带宽相对上代提升，但单卡带宽仍是共享资源，多会话并发时每路分到的有效带宽被摊薄，这正是“并发越高、单帧延迟越抖”的机制来源。</p>\n<p>举例：若某层状态窗口为数千元素、FP16 存储，单层单帧读写不过几十 KiB 量级；乘以层数与会话数后，聚合带宽需求随并发线性上升。当聚合需求逼近单卡 HBM 带宽时，单帧延迟开始随并发劣化，SLO 被击穿的点不在算力饱和而在带宽饱和。工程判断：先测单路单帧的带宽占用，再乘并发上限，与 HBM 带宽对比，若比值接近上限则应优先做状态位宽压缩而非加卡。</p>\n\n<h3 id=\"paper-a-streamable-neural-audio-codec-with-2025-sec-23\">二十三 · 可复算的显存预算模板</h3>\n<p>把上述各项写成一张可逐项填数的表，读者可用实测值替换占位项自行复算。表中不含编造数值，只给结构与量纲。</p>\n<table class=\"mini\">\n<thead><tr><th>项</th><th>符号</th><th>量纲</th><th>是否随并发增长</th><th>优化手段</th></tr></thead>\n<tbody>\n<tr><td>码本（K+1 级）</td><td>\\(M_{\\text{cb}}\\)</td><td>KiB–MiB</td><td>否（共享）</td><td>常驻 HBM、L2 覆盖、FP8 码字</td></tr>\n<tr><td>卷积权重</td><td>\\(M_w\\)</td><td>MiB</td><td>否（共享）</td><td>进程级单例、只读缓存</td></tr>\n<tr><td>单帧峰值激活</td><td>\\(M_{\\text{act}}^{\\text{peak}}\\)</td><td>MiB</td><td>否（按帧复用）</td><td>帧内复用缓冲、算子融合</td></tr>\n<tr><td>单路状态缓存</td><td>\\(M_{\\text{state}}\\)</td><td>MiB</td><td><b>是，线性</b></td><td>FP8 压缩、缩感受野、槽位池</td></tr>\n<tr><td>播放缓冲</td><td>\\(D_{\\text{buf}}\\)</td><td>帧数</td><td>是</td><td>与抖动容忍度联动，不占 HBM</td></tr>\n</tbody>\n</table>\n<p>复算步骤：① 实测 \\(M_{\\text{state}}\\)（单路、单帧稳态）；② 由 HBM 容量扣掉 \\(M_{\\text{cb}}+M_w+M_{\\text{act}}^{\\text{peak}}\\) 得可用额度；③ 相除得 \\(N_{\\max}\\)；④ 用单路单帧带宽乘 \\(N_{\\max}\\) 与 HBM 带宽比对，判断带宽是否先于容量成为约束；⑤ 若带宽先饱和，回到状态位宽与感受野做裁剪，而非扩容。这套顺序的意义在于：容量与带宽是两个独立的饱和点，先到者决定真实并发上限，只算容量会系统性高估部署密度。</p>\n\n<h3 id=\"paper-a-streamable-neural-audio-codec-with-2025-sec-24\">二十四 · 与 SLO 的耦合：状态缓存决定的是抖动而非均值</h3>\n<p>状态缓存的显存账本最终落在 SLO 上，但落点不是平均延迟而是尾延迟。机制在于：状态槽位池满时，新会话要么排队、要么触发卸载换入，两者都在首包路径上引入额外等待；而播放缓冲深度 \\(D_{\\text{buf}}\\) 是吸收这种抖动的唯一缓冲。端到端可容忍的单帧处理抖动上界近似为 \\(D_{\\text{buf}} \\cdot T_{\\text{frame}}\\)，一旦换入延迟或排队延迟超过该上界，即表现为欠载与可闻断续。因此容量规划不能只报“支持 N 路并发”，必须同时报“在 \\(D_{\\text{buf}}\\) 帧缓冲下、尾延迟不超过单帧预算的并发数”。</p>\n<p>工程判断：把状态缓存按会话活跃度分级——活跃会话常驻 HBM、静默会话换出主机内存、超时会话释放槽位；槽位池大小按 \\(N_{\\max}\\) 的保守分位设定，留出换入所需的临时槽。对 RSVQ 而言，K 级串行查询已经线性抬升单帧算力耗时，若再叠加换入等待，首包延迟会被双重推高；因此级数裁剪与状态压缩应联合决策，而不是分别优化。最终落在具体机制上：以单路状态缓存字节数为第一约束、以聚合状态带宽为第二约束、以播放缓冲深度为抖动预算，三者共同定义 Blackwell 上该流式编解码器的可部署并发包络。</p>\n\n<h3 id=\"paper-a-streamable-neural-audio-codec-with-2025-sec-25\">二十五 · 流式编解码的显存账本：状态缓存、码本常驻与串行查询的代价边界</h3>\n<p>这套方案的显存结构与传统 Transformer 推理的 KV cache 账本不同：它没有注意力 KV，取而代之的是每路会话独立的因果卷积帧间状态缓存，加上常驻显存的各级码本。可复算的预算应写成<strong>每路固定成本 × 并发路数 + 全局共享成本</strong>。设每路状态缓存为 <em>S</em> 字节（由因果卷积层数、通道数与感受野覆盖的历史帧数决定），各级码本合计 <em>C</em> 字节（全局只存一份，所有会话共享），并发会话数为 <em>N</em>，则显存占用为：</p>\n<div class=\"formula\">$$ M_{\\text{codec}} = N \\cdot S + C + M_{\\text{runtime}} $$</div>\n<p>关键在于 <em>S</em> 与音频长度无关——状态只保留有限历史感受野，逐帧滚动覆盖，不会像离线解码那样随音频时长线性增长；但 <em>S</em> 与 <em>N</em> 严格线性。容量规划时若沿用离线编解码器的“单模型显存”模型，只算 <em>C</em> 而漏掉 <em>N·S</em>，在并发上升时会出现显存耗尽而非算力耗尽，这是该方案最典型的失效条件。工程上应把 <em>S</em> 作为每路准入成本写入调度器，与 KV cache 分页同一套配额逻辑管理。</p>\n<p>带宽与延迟瓶颈不在 HBM 容量而在<strong>串行最近邻查询</strong>。每帧需依次执行 K 级量化查询，第 k 级必须等第 k−1 级残差算出后才能发起，级间无并行空间。单帧处理耗时近似为：</p>\n<div class=\"formula\">$$ t_{\\text{frame}} \\approx t_{\\text{enc}} + \\sum_{k=0}^{K} t_{\\text{NN}}(k) + t_{\\text{dec}} $$</div>\n<p>其中 <em>t</em><sub>NN</sub>(k) 由该级码本大小与向量维度决定。级数 K 增加会线性抬升 <em>t</em><sub>frame</sub>，而首包延迟直接等于首帧的编码加解码耗时，因此 K 是首包 SLO 与重建质量的直接折中旋钮。小码本降低了单次查询的存储与带宽开销，却把逼近能力上限压在码本容量上：高码率场景要提升质量只能加级数或加码本，两者都推高单帧延迟。这与 Blackwell 上 NVFP4/FP8 量化换取带宽的取舍逻辑同构——精度压缩省带宽但需接受数值上限，此处是码本压缩省查询但需接受重建上限。</p>\n<table class=\"mini\"><thead><tr><th>账本项</th><th>随什么增长</th><th>系统代价</th><th>失效条件</th></tr></thead><tbody><tr><td>帧间状态缓存 S</td><td>并发路数 N</td><td>显存线性占用</td><td>按离线模型估算容量</td></tr><tr><td>码本 C</td><td>级数与码本大小</td><td>常驻显存、查询带宽</td><td>小码本限制高码率质量</td></tr><tr><td>串行查询 K 级</td><td>级数 K</td><td>单帧延迟线性上升</td><td>把多级量化当纯质量手段</td></tr><tr><td>播放缓冲深度</td><td>抖动容忍度</td><td>端到端延迟、欠载风险</td><td>缓冲过浅导致欠载</td></tr></tbody></table>\n<p>复用与卸载的空间有限：码本 <em>C</em> 天然可全局共享，多路并发不重复占用，这是该结构相对大码本单级方案的真实优势；状态缓存 <em>S</em> 则不可跨会话复用，只能按会话生命周期分配与回收，会话结束时立即释放以避免碎片累积。卸载到主机内存对 <em>S</em> 意义不大——每帧都要读写，PCIe 往返会直接击穿单帧延迟预算；可考虑的只有把低频使用的码本级别放到主机侧按需拉取，代价是首次查询的冷启动延迟。监控指标应落在每路缓存字节数、单帧编解码耗时分解、码本查询命中率与播放缓冲欠载次数上，而非 GPU 利用率这类聚合量。材料未给出吞吐、延迟与质量的数值结果，因此上述预算只能作为结构化的容量框架使用，不能作为低延迟部署的可核验证据引用。</p>\n<h3 id=\"paper-a-streamable-neural-audio-codec-with-2025-sec-26\">二十六 · 逐帧到达下的批处理边界</h3>\n<p>实时通信的编解码器与 LLM 服务的批处理假设不同：LLM 请求有明确的“输入—生成—结束”三段，而音频流是无限长、等间隔到达的帧序列。每路会话每帧都要触发一次编码与一次解码，帧到达即处理，不允许跨帧攒批。这直接决定了连续批处理（continuous batching）在此处的形态——批不是由请求队列驱动，而是由帧时钟驱动：一个调度步内，把当前所有活跃会话的“待处理帧”拼成一个 batch，前向完成后立即释放，下一帧时钟再重新组批。批大小因此等于活跃会话数，而不是队列长度；会话加入与退出只改变下一拍的批形状，不打断当前拍的执行。</p>\n<p>代价落在两个地方。其一是批形状抖动：会话数从 1 跳到 N 时，单帧处理耗时随 batch 增大而上升，若帧时钟固定，尾帧就会挤压播放缓冲。其二是状态缓存：每路会话的因果卷积感受野缓存是固定大小，显存占用为</p>\n<div class=\"formula\">$$ M_{\\text{state}} = N_{\\text{sess}} \\times \\big( S_{\\text{enc}} + S_{\\text{dec}} \\big) \\times b_{\\text{state}} $$</div>\n<p>其中 $S_{\\text{enc}}$、$S_{\\text{dec}}$ 分别为编解码器每层保留的历史帧数，$b_{\\text{state}}$ 为每帧状态的字节数。这个量随并发线性增长，与音频时长无关——这正是流式设计相对离线设计的显存优势，也是容量规划必须按会话数而非按分钟数估算的原因。工程判断：把 batch 上限设为“帧时钟内能完成的会话数”，而不是显存能容纳的会话数；后者是硬上限，前者才是 SLO 上限。</p>\n\n<h3 id=\"paper-a-streamable-neural-audio-codec-with-2025-sec-27\">二十七 · chunked prefill 在音频侧的对应物</h3>\n<p>LLM 的 chunked prefill 解决的是长 prompt 一次性占满算力、拖垮 decode 尾延迟的问题。音频编解码器没有 prompt，但有一个结构同构的问题：首帧。首帧到达时，因果卷积的感受野缓存为空，需要按帧序“预热”若干帧才能进入稳态；若把预热帧与稳态帧混在同一拍里，首帧会话的处理耗时显著高于稳态会话，尾延迟被拉高。可行的做法是把预热拆成固定粒度的 chunk，每拍只推进一个 chunk，与稳态帧共享同一 batch，使单拍工作量有上界。</p>\n<p>伪代码思路：调度器为每路会话维护 <code>warmup_remaining</code>，每拍取 <code>min(warmup_remaining, chunk)</code> 帧并入批；稳态会话固定取 1 帧。批内总帧数被硬性截断为 <code>F_max</code>，超出部分留到下一拍。这样单拍耗时的方差被压到与 <code>F_max</code> 同阶，而不是与“最慢会话的预热长度”同阶。代价是首包延迟：预热被拉长到若干拍，首帧输出时间从“单帧耗时”变成“chunk 数 × 单拍耗时”。这是一个明确的取舍——用首包延迟换尾延迟的稳定性，在并发高、抖动敏感的场景里通常值得。</p>\n<p>具体例子：某路会话在 t=0 到达，chunk=4，预热需 16 帧，则首帧在第 4 拍末输出；若不分 chunk，该会话独占一拍完成 16 帧预热，同拍内其他会话的稳态帧被迫等待，尾延迟抬升数倍。前者牺牲该会话的首包，后者牺牲全体会话的抖动。</p>\n\n<h3 id=\"paper-a-streamable-neural-audio-codec-with-2025-sec-28\">二十八 · 优先级与抢占：谁让出算力</h3>\n<p>实时通信的会话并非等价：正在说话的会话对延迟敏感，静音或聆听中的会话可以降级。优先级调度在这里的落点是“每拍批内配额”——给活跃说话会话保留固定的帧槽位，剩余槽位才分配给背景会话。抢占则发生在批组装阶段而非执行中途：若某拍配额不足以容纳所有高优先级帧，低优先级会话的帧被推迟到下一拍，其状态缓存保持不变（因果卷积的状态是纯函数于历史帧，推迟不破坏正确性），只是播放缓冲被消耗一格。</p>\n<p>代价是播放缓冲深度。设帧长为 $T_f$，缓冲深度为 $D$ 帧，则端到端抖动容忍度为 $D \\cdot T_f$；一次抢占推迟消耗一格缓冲，连续 $D$ 次推迟即欠载。因此抢占策略必须与缓冲深度联合设计：</p>\n<div class=\"formula\">$$ P_{\\text{underrun}} \\approx \\Pr\\!\\left( \\sum_{i=1}^{D} \\mathbb{1}[\\text{preempted}_i] = D \\right) $$</div>\n<p>工程上更稳的做法是给每路会话设“欠载余量”计数器，接近耗尽时临时提升其优先级，形成负反馈。这比全局静态优先级更抗突发。注意：多级量化的串行查询使单帧耗时随级数 K 线性上升，抢占一次的实际代价是 K 次级数对应的最近邻查询被推迟，而不是一帧的固定开销——级数越多，缓冲消耗越快。</p>\n\n<h3 id=\"paper-a-streamable-neural-audio-codec-with-2025-sec-29\">二十九 · 分离式预填/解码的音频映射</h3>\n<p>分离式（disaggregated）预填/解码在 LLM 里是把 compute-bound 的 prefill 与 memory-bound 的 decode 放到不同资源池。音频编解码器的对应物是编码侧与解码侧的分离：编码器是 compute-bound（因果卷积 + K 级量化查询），解码器是 memory-bound（反卷积 + 码本查表 + 状态读写）。两者对 SM 占用、显存带宽、状态缓存的需求不同，混布在同一进程里会互相挤压。</p>\n<p>分离部署的收益是重叠首帧处理：发送端编码完首帧即把码流推给接收端解码池，编码池继续处理后续帧，两池的批时钟可以独立。代价是跨池传输引入的额外一跳延迟，以及码流打包/解包的开销。判断准则：当单帧编码耗时与单帧解码耗时相近时，分离的收益被传输开销抵消；当两者差异显著（例如 K 较大导致编码侧串行查询占主导），分离能把解码池的批填满，提升整体吞吐。表格对比两种拓扑：</p>\n<table class=\"mini\"><thead><tr><th>拓扑</th><th>首包延迟构成</th><th>吞吐瓶颈</th><th>显存占用</th></tr></thead><tbody><tr><td>同进程混布</td><td>编码 + 解码串行</td><td>编码侧 K 级查询</td><td>两套状态缓存同池</td></tr><tr><td>分离双池</td><td>编码 + 传输 + 解码</td><td>解码池批填充率</td><td>按池分别规划</td></tr></tbody></table>\n<p>具体例子：K 级量化使编码侧单帧耗时远高于解码侧时，混布下解码器空转等待编码结果，SM 利用率被拉低；分离后解码池可用更小批、更高频率拉取码流，尾延迟由解码池的批时钟决定而非编码池的长尾。</p>\n\n<h3 id=\"paper-a-streamable-neural-audio-codec-with-2025-sec-30\">三十 · 尾延迟的三个抓手</h3>\n<p>尾延迟（p99）在流式音频里比均值更重要，因为一次欠载就是一次可听见的断音。三个抓手按收益排序：</p>\n<ul>\n<li><b>批形状上界</b>：硬截断每拍帧数 <code>F_max</code>，把单拍耗时的上界从“最慢会话”变为常数。代价是高并发时部分会话被推迟，需配合优先级。</li>\n<li><b>量化级数的延迟预算</b>：K 级串行查询线性抬升单帧耗时，级数是首包延迟与重建质量的直接折中。把 K 纳入调度预算——高优先级会话用较低 K 保延迟，背景会话用较高 K 保质量——比全局固定 K 更能压尾。</li>\n<li><b>状态缓存的预分配与隔离</b>：按会话数预分配固定大小的状态缓存池，避免运行期动态增长导致的显存碎片与分配抖动；缓存池满即拒绝新会话，而不是让已有会话的批形状被挤压。</li>\n</ul>\n<p>三者的共同点是：都把“不可控的长尾”转化为“可控的常数上界 + 明确的降级路径”。尾延迟的本质不是平均算力不够，而是最慢那一拍的算力需求超出了帧时钟预算；调度器的职责是让最慢那一拍可预测。</p>\n\n<h3 id=\"paper-a-streamable-neural-audio-codec-with-2025-sec-31\">三十一 · 时延与吞吐的取舍落点</h3>\n<p>流式编解码器的吞吐定义与离线不同：不是“每秒处理多少秒音频”，而是“在帧时钟约束下能同时维持多少路会话”。设单拍预算为 $T_f$，单帧处理耗时为 $c(N)$（随批大小 $N$ 增长），则可行会话数满足</p>\n<div class=\"formula\">$$ N \\cdot c(N) \\le T_f \\quad\\Rightarrow\\quad N_{\\max} = \\max\\{N : N \\cdot c(N) \\le T_f\\} $$</div>\n<p>这个不等式揭示了取舍的落点：提高 $N$ 提升吞吐，但 $c(N)$ 随批增大而上升，$N_{\\max}$ 由帧时钟硬性封顶。要突破封顶，只能降低单帧耗时——减少 K、缩小码本、缩短感受野，每一项都以重建质量为代价。因此容量规划的正确姿势是先定 SLO（首包延迟上界、欠载率上界），再反解 $N_{\\max}$，最后按 $N_{\\max}$ 乘以每路状态缓存估算显存。材料未给出可核验的吞吐与延迟数值，上述不等式只能作为结构性判断：它说明该设计的吞吐上限由帧时钟与单帧串行查询次数共同决定，而非由码本存储或显存带宽单独决定。</p>\n<p>最后落在具体机制上：调度器应把 K 级量化的串行查询视为一等公民的延迟预算项，与批形状、状态缓存池一起纳入每拍决策；任何把多级量化当作纯质量旋钮、把批大小当作纯吞吐旋钮的配置，都会在尾延迟上付出代价，而这个代价在播放缓冲欠载的那一刻才显现。</p>\n\n<h3 id=\"paper-a-streamable-neural-audio-codec-with-2025-sec-32\">三十二 · 帧到达即处理的调度边界：连续批处理为何在这里失效</h3>\n<p>这套编解码器的数据配方明确写着“帧到达即触发编码，不允许跨帧攒批”，这一条直接决定了它不能套用 LLM 推理里那套连续批处理（continuous batching）的收益模型。连续批处理的前提是请求之间彼此独立、可被调度器拼进同一迭代步，从而用更大的矩阵乘摊薄权重读取；而这里每一路会话都携带独立的因果卷积状态缓存，帧间状态必须严格按序传递，把不同会话的帧拼成一批只会让状态寻址复杂化，却换不来算力摊薄——因为单帧的量化查询是串行 K 级最近邻，批内并行度受限于级数而非批大小。真正可做的“批”只有一种：同一会话内把编码与解码分离部署，让第 i 帧的解码与第 i+1 帧的编码在时间上重叠，用流水线而非批处理隐藏单帧耗时。代价是每路会话要额外占用一份在途帧缓冲，显存随并发线性增长，收益上限被单帧串行链的长度锁死。</p>\n<p>于是时延与吞吐的取舍退化为一个纯排队问题。设单帧编码耗时为 <span>t_e</span>、解码耗时为 <span>t_d</span>、量化级数为 K、每级最近邻查询耗时为 <span>t_q</span>，则首包延迟近似为</p>\n<div class=\"formula\">$$ T_{\\text{first}} \\approx t_e + K\\,t_q + t_d,\\qquad \\text{稳态吞吐} \\approx \\frac{N_{\\text{sess}}}{\\max(t_e,\\,t_d)} $$</div>\n<p>注意吞吐分母取的是编解码两者较大者而非之和——这正是分离式预填/解码思路在此处的对应物：把编码端和解码端放在不同执行单元上，稳态吞吐由瓶颈侧决定，而首包延迟仍是两侧串行之和。级数 K 是唯一同时出现在两个式子里的变量：加一级提升重建上限，却线性抬升 <span>\\(T_{\\text{first}}\\)</span>；若瓶颈侧本就是解码，加级还可能把瓶颈从编码侧搬到解码侧，吞吐随之掉档。这就是“多级量化当纯质量手段”这一失败模式的算术根源。</p>\n<p>尾延迟的压缩不靠平均耗时，而靠播放缓冲深度与抢占策略的配合。接收端逐帧拉取解码、重建帧直接进播放缓冲，缓冲深度决定了能容忍多少帧的处理抖动：深度越浅，端到端延迟越低，但任一顿挫即触发欠载；深度越深，欠载风险下降而交互延迟上升。工程上应把优先级给“即将被播放的帧”，对落后于播放指针的会话执行抢占式降级——临时削减量化级数 K 或跳过低收益的残差级，用质量换准时，而不是让整条流水线等一个慢帧。容量规划则必须按每路状态缓存大小乘以并发数估算显存，任何沿用离线编解码器“显存与音频长度相关”的模型都会低估占用。最后一条判断：材料未给出吞吐、延迟与质量的数值结果，把该工作直接当作低延迟部署证据引用是不成立的；能落地的只有机制层面的结论——首包延迟与单帧串行链挂钩、显存与并发路数线性挂钩，这两条足以约束调度器与容量模型的设计方向。</p>\n<h3 id=\"paper-a-streamable-neural-audio-codec-with-2025-sec-33\">三十三 · 切分对象不是矩阵，是帧与状态</h3>\n<p>在 Blackwell 上讨论这套编解码器的并行，先要纠正一个直觉：它的可切分维度不是训练意义上的大矩阵乘法，而是“帧”与“会话状态”两类资源。编码器与解码器都是因果卷积堆叠，帧间状态缓存保留历史感受野，因此单路会话在时间上是严格串行的——第 n 帧的解码必须等第 n−1 帧的状态写入。这意味着张量并行（TP）在这类模型上几乎没有收益：单帧特征维度有限，切分后每卡只拿到一小块通道，却要为每次因果卷积的边界做激活拼接，通信量相对计算量反而占优。真正可切的是数据并行（DP）意义上的会话维度：把并发路数分摊到多卡，每卡持有独立的编码器/解码器状态缓存。流水并行（PP）则对应“编码段—量化段—解码段”三段式切分，适合把发送端与接收端分离部署以重叠首帧处理。专家并行（EP）在此不适用，因为模型没有 MoE 结构；若强行套用，只会把多级量化的串行查询拆到不同设备，制造不必要的跨卡往返。</p>\n<p>代价判断可以直接写出来。设并发会话数为 N、每路状态缓存为 S 字节、单卡可用显存为 M，则 DP 的可承载路数为：</p>\n<div class=\"formula\">$$ N_{\\max} = \\left\\lfloor \\frac{M - W_{\\text{codebook}} - W_{\\text{weights}}}{S} \\right\\rfloor $$</div>\n<p>其中码本常驻显存 W_codebook 与权重 W_weights 是每卡固定开销。这个式子说明：流式状态缓存与并发路数线性相关，容量规划必须按“每路缓存 × 并发数”估算，而不能沿用离线编解码器“显存随音频长度线性增长”的旧模型。举个具体例子：一路 48 kHz 语音按固定帧长切分，编码器每层因果卷积保留固定长度的历史激活，若每路缓存为几百 KB 量级，单卡承载数十路尚可，但一旦并发上升到数百路，状态缓存就会挤占本已紧张的权重与码本空间，此时增加卡数比增大单卡更划算——因为状态缓存无法跨卡共享。</p>\n\n<h3 id=\"paper-a-streamable-neural-audio-codec-with-2025-sec-34\">三十四 · NVLink 5 与 NVSwitch：把 All-to-All 压进机柜</h3>\n<p>Blackwell 世代的 GB200/GB300 NVL72 把 72 颗 GPU 放进同一 NVLink 域，NVLink 5 的每 GPU 双向带宽与 NVSwitch 的全互联拓扑，使得 All-to-All 与 All-Reduce 不再必然穿越 InfiniBand。对这套编解码器而言，通信模式其实很窄：DP 副本之间几乎不需要梯度同步（推理无梯度），真正产生集合通信的是两种场景——其一是 PP 切分下编码段向解码段传递量化索引码流，其二是多路会话的码流聚合与分发。前者是点对点的小消息，后者在集中式网关架构下退化为 All-to-All：每张卡把自己编码出的码流发给负责该会话解码的卡。NVSwitch 的价值就在这里——All-to-All 的跳数被压到一级交换，避免了跨节点树形归约的多次往返。</p>\n<p>通信是否成为瓶颈，取决于“每帧码流字节数 ÷ 单帧计算耗时”与链路带宽的比较。设每帧码流为 B 字节、单帧编解码耗时为 T_frame、链路有效带宽为 BW，则通信占用时间比为：</p>\n<div class=\"formula\">$$ \\rho = \\frac{B}{T_{\\text{frame}} \\cdot BW} $$</div>\n<p>当 ρ 远小于 1 时，通信被计算完全掩盖；当 ρ 接近或超过 1 时，链路成为首包延迟的一部分。这里的关键事实是：RSVQ 的设计本身就在压低 B——多级小码本输出的量化索引远小于单级大码本的索引位宽，码流按帧打包后每帧只有很小的字节数。因此在这套模型上，NVLink 5 的带宽对单路流式会话是过剩的；瓶颈更可能出现在“小消息高频次”的形态上：每帧一次的点对点传递若未做批处理合并，协议开销与内核启动开销会主导延迟，而不是有效带宽。工程判断是：优先把同一会话连续多帧的码流合并成一次传输，用消息聚合换取更少的往返次数，而不是去追更高的链路带宽。</p>\n\n<h3 id=\"paper-a-streamable-neural-audio-codec-with-2025-sec-35\">三十五 · All-Reduce 在此处基本无事可做</h3>\n<p>需要明确一点以免误配资源：推理阶段的这套编解码器没有需要 All-Reduce 的大张量。TP 切分若被强行引入，因果卷积的每一层都需要在切分边界做激活的 All-Reduce 或 All-Gather，其通信量与层数、通道切分数成正比，而单帧的计算量又不足以掩盖它——这正是 TP 在此不划算的量化理由。真正需要集合通信的只剩“码本同步”这类低频操作：多卡各自持有码本副本时，码本更新（若存在在线校准）才需要一次小规模广播，频率远低于帧率。因此在这套系统的通信预算里，All-Reduce 应被视为近乎零成本的偶发操作，而 All-to-All 才是需要建模的对象。把优化精力放在 All-Reduce 调参上，属于典型的资源错配。</p>\n<p>具体例子：若把编码器按通道切成两份放到两张卡上，每帧每层因果卷积都要交换边界激活，假设每层交换量为 C 字节、共 L 层，则单帧通信量为 L·C，而单帧有效计算只有一次前向。由于帧到达即触发编码、不允许跨帧攒批，这个通信量无法被批处理摊薄，直接叠加进首包延迟。结论是：这套模型的并行拓扑应默认“单卡单路、DP 扩会话”，把 TP 留给真正的大矩阵模型，而不是这里的卷积编解码器。</p>\n\n<h3 id=\"paper-a-streamable-neural-audio-codec-with-2025-sec-36\">三十六 · NIXL 传输：把状态缓存搬对地方</h3>\n<p>NIXL 在这套系统里的角色不是加速帧内计算，而是解决“状态缓存与码流该放在哪张卡、怎么搬”的问题。流式会话的状态缓存是固定显存、随并发线性增长的资源，而会话的归属可能因负载均衡而迁移：某张卡过载时，需要把若干路会话的编码器/解码器状态整体转移到另一张卡。NIXL 提供的点对点传输抽象让这种迁移可以绕过主机内存中转，直接在 GPU 显存之间搬运状态块。代价模型很直接：迁移一路会话的耗时约等于 S/BW_transfer，其中 S 是该路状态缓存字节数；在迁移窗口内，该路会话无法推进帧，表现为播放缓冲欠载风险上升。因此迁移策略应以“低频、成批、避开首包关键路径”为原则，而不是逐帧动态调度。</p>\n<p>另一个 NIXL 的用武之处是分离式部署：编码端与解码端位于不同节点时，码流通过 NIXL 从编码卡直达解码卡显存，避免“GPU→主机→网络→主机→GPU”的四次拷贝。对每帧只有小字节数的码流而言，这种直达路径削减的是固定拷贝开销而非带宽占用，收益体现在首包延迟的常数项上。工程上要监控的指标因此不是链路利用率，而是每帧传输的端到端时延分布与播放缓冲欠载次数——后者才是通信是否真正伤及 SLO 的直接证据。</p>\n\n<h3 id=\"paper-a-streamable-neural-audio-codec-with-2025-sec-37\">三十七 · 通信何时成为瓶颈：三个判据</h3>\n<p>把前面的分析收敛成可操作的判据。第一，看 ρ 是否逼近 1：若每帧码流字节数相对单帧计算耗时偏大，或链路有效带宽被多路会话共享后摊薄，通信就会浮出水面。多路并发时有效带宽按路数分摊，ρ 随并发线性上升，这是最容易被忽视的拐点。第二，看消息频次而非消息大小：每帧一次的小消息在未聚合时，协议与内核开销可能远超有效载荷传输时间，此时瓶颈是往返次数而不是带宽。第三，看状态缓存迁移是否落在首包路径上：迁移窗口内的会话停顿会直接转化为欠载，属于“通信引发的 SLO 违规”，与带宽高低无关。</p>\n<table class=\"mini\"><thead><tr><th>判据</th><th>观测对象</th><th>代价落点</th><th>处置</th></tr></thead><tbody><tr><td>ρ 接近 1</td><td>每帧码流字节 / (单帧耗时 × 有效带宽)</td><td>首包延迟常数项抬升</td><td>合并多帧码流、提高单次载荷</td></tr><tr><td>消息频次过高</td><td>每帧传输次数与往返时延</td><td>协议与内核开销主导</td><td>批量聚合、减少同步点</td></tr><tr><td>状态迁移入关键路径</td><td>迁移窗口内欠载次数</td><td>会话停顿、抖动</td><td>成批迁移、错峰调度</td></tr></tbody></table>\n<p>具体例子：一路会话在单卡上编码、另一卡上解码，每帧码流经 NVLink 直达。若每帧传输一次且不做聚合，即便单次传输时延很小，帧率乘以往返次数仍会吃掉可观的首包预算；把连续若干帧合并为一次传输后，往返次数下降，ρ 随之下降，首包延迟的通信分量被压缩。这个例子的要点是：在这套以“帧”为调度单位的系统里，通信优化的抓手是聚合粒度，而不是链路代际。</p>\n\n<h3 id=\"paper-a-streamable-neural-audio-codec-with-2025-sec-38\">三十八 · 拓扑选择的工程结论</h3>\n<p>综合来看，这套可流式神经编解码器的并行与通信设计应遵循一条窄路径：以 DP 扩并发会话、以 PP 分离编码与解码两段、以 NVLink 5/NVSwitch 承载小消息的 All-to-All 与点对点码流、以 NIXL 处理状态缓存的成批迁移与跨节点直达。TP 与 EP 在此没有结构性收益，强行引入只会把串行的多级量化查询拆散，制造跨卡往返并抬升单帧延迟——而单帧延迟正是首包延迟的唯一决定项。容量规划的核心约束不是算力，而是每路状态缓存乘以并发数所得的显存占用；通信规划的核心约束不是带宽，而是每帧消息的聚合粒度与迁移窗口的错峰安排。</p>\n<p>最后落在一个具体机制上：多级残差量化的每一级都是一次串行最近邻查询，级数 K 直接线性抬升单帧处理耗时 T_frame。当 T_frame 增大时，ρ = B/(T_frame·BW) 反而下降——也就是说，量化级数越多，通信越容易被计算掩盖，但首包延迟本身变长。这个反向关系说明：在这套系统里，通信与计算不是互相争夺预算的两方，而是共同被“单帧串行链”约束。任何并行或通信优化，若不能缩短这条串行链或降低其上的消息往返次数，就不会改善 SLO；反之，把状态缓存管好、把码流聚合好，比换一代互联更能守住首包延迟的底线。</p>\n\n<h3 id=\"paper-a-streamable-neural-audio-codec-with-2025-sec-39\">三十九 · 并行切分与通信：编解码器为何几乎不碰 All-to-All</h3>\n<p>把 RSVQ 编解码器放进 TP/EP/PP/DP 的切分讨论里，先要认清它的并行形态：这是一个按会话、按帧推进的有状态流式模型，不是以矩阵乘为主体的大模型。TP 切分对它意义有限——编码器因果卷积与多级量化器的参数量小，切分后每帧都要做跨卡归约，归约延迟直接进入单帧耗时，反而抬高首包延迟；PP 更不适用，帧级流水线本身已是串行因果链，再按层切分只会让每帧多出跨卡跳数。真正可行的是 DP：每路会话独立持有编码器与解码器状态缓存，卡间无需交换激活，只在码流层面汇聚。此时通信代价近似为零，瓶颈回到单帧的 K 次串行最近邻查询。代价公式很直接：</p>\n<div class=\"formula\">$$ T_{\\text{frame}} \\approx \\sum_{k=0}^{K} t_{\\text{quant}}^{(k)} + t_{\\text{conv}} + \\mathbb{1}_{\\text{TP}&gt;1}\\cdot t_{\\text{AR}} $$</div>\n<p>其中 $t_{\\text{AR}}$ 是每帧一次 All-Reduce 的时延。只要 TP&gt;1，这个附加项就按帧数线性累积，与音频总长无关但与并发路数相乘，是典型的“通信吃掉 SLO”的场景。NVLink 5 与 NVSwitch 提供的高带宽并不改变这一点：小消息、高频次的逐帧归约受限于启动时延而非链路带宽，NIXL 的点对点传输更适合码流搬运而非激活同步。</p>\n<table class=\"mini\"><thead><tr><th>切分方式</th><th>每帧通信</th><th>主要代价</th></tr></thead><tbody><tr><td>DP（按会话）</td><td>无激活交换</td><td>状态缓存随并发线性增长</td></tr><tr><td>TP（按通道）</td><td>逐帧 All-Reduce</td><td>启动时延进入首包预算</td></tr><tr><td>PP（按层）</td><td>逐帧点对点</td><td>流水气泡拉长单帧耗时</td></tr></tbody></table>\n<p>失效条件因此很明确：当并发路数上升、单帧预算被压到毫秒级时，任何逐帧集合通信都会把延迟抖动放大成播放缓冲欠载；当码本与状态缓存常驻显存、每路缓存固定时，DP 的容量上限由显存除以单路缓存决定，而非由算力决定。工程判断是：该方案应优先采用单卡多会话或纯 DP 拓扑，把 NVLink 留给码流与批调度元数据的传输，避免把 TP 的归约路径引入帧级关键路径；只有在单帧算力确实不足、且能把 K 级串行查询与归约重叠时，才考虑受限的 TP 切分。</p>\n<h3 id=\"paper-a-streamable-neural-audio-codec-with-2025-sec-40\">四十 · 精度塌陷：残差链断裂的三种形态</h3>\n<p>RSVQ 的推理正确性依赖一条逐级收敛的残差链：第 k 级量化器只应看到前 k−1 级重建后的真实残差。精度塌陷的本质是这条链在数值上被切断，而流式部署中最常见的切断点不在量化器本身，在状态缓存与量化索引的交接处。</p>\n<p>第一种形态是<b>索引错位</b>。码流按帧打包，接收端逐帧拉取，一旦发送端与接收端的帧边界约定不一致（例如编码端下采样后的帧率与解码端反卷积上采样的对齐差一帧），解码器会把第 n 帧的索引喂给持有第 n−1 帧状态的因果反卷积。因果卷积的感受野是单向累积的，错一帧不会自愈，误差沿状态缓存向后传播，表现为持续的背景嘶声或音色漂移，而非单帧爆音。第二种形态是<b>残差饱和</b>：小码本容量有限，当某一帧的残差幅度超出末级矢量量化器的覆盖范围，最近邻查询会返回码本边界上的码字，残差无法继续收敛，重建信号在该帧出现削顶。第三种形态是<b>状态缓存溢出或截断</b>：帧间缓存按感受野保留历史，若为省显存把缓存长度裁到小于感受野，因果卷积在每帧边界处丢失上下文，重建波形在帧接缝处出现周期性不连续。</p>\n<p>诊断上不要只看重建波形的整体失真度，那会把偶发错位平均掉。应逐帧计算残差能量比：</p>\n<div class=\"formula\">$$ \\rho_k = \\frac{\\lVert r_k \\rVert_2}{\\lVert r_{k-1} \\rVert_2},\\quad r_k = x - \\hat{x}_{k-1} $$</div>\n<p>健康的多级量化应使 ρ_k 随 k 单调下降；若某一级之后 ρ_k 不再下降甚至回升，说明该级码本对该帧残差已饱和，是容量问题而非数值精度问题。若 ρ_1 本身在帧间剧烈抖动而 ρ_k 平稳，则指向索引错位或缓存截断。工程代价直接：残差饱和帧需要提高码率或增加级数，而增加一级意味着每帧多一次串行最近邻查询，单帧延迟线性上升，首包延迟随之抬升。</p>\n\n<h3 id=\"paper-a-streamable-neural-audio-codec-with-2025-sec-41\">四十一 · OOM：状态缓存是随并发线性增长的隐性成本</h3>\n<p>用离线编解码器的显存模型做容量规划，是这套系统最容易踩的坑。离线模型的显存由码本与固定激活构成，与音频长度无关；而流式 RSVQ 的显存由三部分组成：常驻码本、每路会话的编码器与解码器状态缓存、以及为平滑抖动而设的播放缓冲。码本是所有会话共享的只读数据，规模由级数与各级码本大小决定；状态缓存则是每路独占，大小由因果卷积感受野与帧长决定，与并发路数严格线性相关。</p>\n<p>于是容量估算应写成：</p>\n<div class=\"formula\">$$ M_{\\text{total}} = M_{\\text{codebook}} + N_{\\text{sess}} \\times \\left( S_{\\text{enc}} + S_{\\text{dec}} \\right) + M_{\\text{buf}} $$</div>\n<p>其中 S_enc、S_dec 是单路编解码状态缓存，N_sess 是并发会话数。OOM 的典型触发不是稳态并发，而是<b>并发爬坡期的状态分配</b>：新会话建立时一次性分配两份状态缓存，若分配策略不做上限控制，瞬时并发尖峰会把显存推过阈值，而此时正在服务的会话又不能被驱逐——驱逐一路等于掐断一通实时通话。因此正确的做法是把状态缓存做成预分配的池，池满即拒绝新会话接入（在信令层返回忙），而不是让分配器在运行时失败。监控上应盯“状态缓存占用 / 池容量”这一比值及其爬坡斜率，而不是只看总显存利用率；后者会被码本这个常量稀释，掩盖真实压力。</p>\n<p>一个具体判断：若观察到总显存平稳但新会话接入延迟上升、且伴随分配失败重试，说明池已接近饱和，此时扩容应加副本而非加卡内并发，因为单卡并发上限由状态缓存池而非算力决定。</p>\n\n<h3 id=\"paper-a-streamable-neural-audio-codec-with-2025-sec-42\">四十二 · 批抖动与尾延迟：帧到达即处理的代价</h3>\n<p>实时通信的负载形态决定了不能跨帧攒批：帧到达即触发编码，攒批就是往首包延迟里加等待。但这不意味着批处理不存在——多路会话的帧在时间上天然错开，调度器会把同一时刻到达的若干路帧拼成一个批送进量化与解码算子，以提高码本查询与反卷积的算力利用率。批抖动就出在这里：批大小随到达率波动，而多级量化的串行查询使单帧耗时对批大小敏感，批一大，队尾那一路的帧就要等前面所有帧的查询完成。</p>\n<p>尾延迟的放大机制可以用排队近似刻画。设单批服务时间为 T(b)，b 为批大小，多级量化的串行结构使 T(b) 随 b 增长而增长（每级查询都要遍历批内全部帧），则某一路帧的等待时间近似为：</p>\n<div class=\"formula\">$$ W \\approx \\sum_{j=1}^{K} \\left( \\frac{b_j}{C_j} \\right) $$</div>\n<p>这里 K 是量化级数，b_j 是第 j 级查询时的批内帧数，C_j 是该级的查询吞吐。级数越多，求和项越多，尾延迟对批大小的敏感度越高。这解释了为什么“把级数从 K 加到 K+1 换质量”在离线测试里看不出问题，上线后却表现为 P99 首包延迟劣化：稳态平均延迟只涨一点，但队尾帧要穿过更多级串行队列。</p>\n<p>诊断批抖动要看两个量的相关性：批大小的时间序列与 P99 单帧耗时的相关性。若强相关，说明调度器的批上限设得过高，应给批大小设硬上限并按级数反比缩放；若弱相关而 P99 仍高，则问题在单路内部（例如某一路的状态缓存异常增长导致其帧处理变慢），应转向按会话维度的耗时分解。监控指标应包含每级量化器的查询耗时直方图，而不是只监控端到端首包延迟——后者是多个级串联后的结果，无法定位是哪一级在拖尾。</p>\n\n<h3 id=\"paper-a-streamable-neural-audio-codec-with-2025-sec-43\">四十三 · 静默降级：播放缓冲欠载与质量档位的隐性切换</h3>\n<p>实时音频系统最危险的失败不是报错，是听感变差却不报警。RSVQ 流式链路上有两类静默降级。第一类是<b>播放缓冲欠载</b>：接收端逐帧拉取解码，播放缓冲深度决定端到端抖动容忍度。当解码侧因批抖动或状态缓存争用而短暂变慢，缓冲被抽干，播放端要么插入静音帧、要么重复上一帧，听感上是周期性咔哒声。系统不会抛异常，因为每一帧都“成功”解码了，只是没赶上播放时钟。第二类是<b>质量档位隐性下调</b>：为守住首包延迟 SLO，调度器可能在负载高时减少量化级数或缩小参与查询的码本范围，重建质量下降但码流格式不变，接收端无从察觉。</p>\n<p>这两类降级的共同诊断难点是缺乏“应有质量”的参照。可行的手段是在发送端保留一个轻量的旁路校验：对每帧的残差能量比 ρ_k 做滑动统计，当末级 ρ_K 的中位数在时间窗内上移，即判定重建上限被压低，触发告警。对播放缓冲，应监控欠载次数与缓冲深度的最小值，而不是平均深度——平均值会被深缓冲时段拉高，掩盖瞬时抽干。</p>\n<p>回滚策略要按降级类型分开。质量档位下调属于配置层，回滚是把级数与码本档位恢复到标称值，代价是单帧延迟上升，因此回滚必须与并发准入联动：先收紧新会话接入，再恢复档位，避免延迟与并发同时抬升造成雪崩。播放缓冲欠载属于调度层，回滚是降低批上限、把解码从与编码共享的算力池中分离出来，代价是吞吐下降。两类回滚都不应触碰码本常驻数据，因为重载码本会造成所有在途会话的状态缓存失效，等于强制全体重连。</p>\n\n<h3 id=\"paper-a-streamable-neural-audio-codec-with-2025-sec-44\">四十四 · 监控面与定位顺序：从端到端指标拆到单级查询</h3>\n<p>这套系统的可观测性应组织成三层，且定位时必须自上而下逐层拆，不能跳层。</p>\n<table class=\"mini\"><thead><tr><th>层级</th><th>指标</th><th>指向的失败模式</th></tr></thead><tbody><tr><td>会话层</td><td>首包延迟 P50/P99、播放缓冲欠载次数、单帧编解码耗时</td><td>尾延迟、静默降级</td></tr><tr><td>资源层</td><td>状态缓存池占用比及爬坡斜率、码本查询吞吐、批大小时间序列</td><td>OOM、批抖动</td></tr><tr><td>数值层</td><td>逐级残差能量比 ρ_k 分布、各级最近邻查询耗时直方图、码本命中分布</td><td>精度塌陷、残差饱和</td></tr></tbody></table>\n<p>定位顺序有明确的判据。先看会话层：若首包延迟 P99 劣化而 P50 平稳，直接跳资源层查批大小与 P99 单帧耗时的相关性，这是批抖动的签名；若 P50 与 P99 同步上移，先查状态缓存池占用比，池接近饱和时分配重试会均匀拖慢所有会话。再下到数值层：若资源层指标正常而听感异常，查 ρ_k 分布——末级 ρ_K 上移是残差饱和，ρ_1 帧间抖动是索引错位，两者对应的修复动作完全不同（前者加级数或码本，后者查帧边界对齐）。</p>\n<p>一个具体例子：某路会话报告周期性咔哒声，会话层显示该路首包延迟正常但欠载次数上升，资源层显示全局批大小平稳、状态缓存池占用正常，数值层显示该路 ρ_K 分布与健康会话无异。三层都“正常”，说明问题不在算力与量化，而在该路自身的帧到达节奏——发送端与接收端的帧时钟存在漂移，缓冲深度被缓慢抽干。这类问题的修复不在推理栈内，而在时钟同步与缓冲深度的自适应调整上。这个例子说明：监控面必须包含按会话维度的分解，全局指标会把单路时钟问题完全平均掉。</p>\n\n<h3 id=\"paper-a-streamable-neural-audio-codec-with-2025-sec-45\">四十五 · 回滚的工程边界：什么能动，什么不能动</h3>\n<p>回滚不是把配置改回去那么简单，在流式 RSVQ 上它受一个硬约束：状态缓存与码本版本绑定。码本一旦重载，所有在途会话的因果卷积状态所对应的量化语义就变了，缓存里的历史感受野不再与当前码本一致，继续解码会产生系统性失真。因此码本变更必须走“新会话用新码本、旧会话自然排空”的路径，而不能热切换。这条边界决定了回滚的时间尺度：配置层回滚是秒级，码本层回滚是会话生命周期级。</p>\n<p>由此得出三条工程判断。其一，级数与码本档位应做成会话建立时确定的不可变参数，运行期只允许在预设档位间切换且切换仅对新会话生效，避免在途会话的质量语义漂移。其二，状态缓存池的容量应预留爬坡余量，回滚动作（收紧准入、降批上限）必须能在不驱逐在途会话的前提下执行，否则回滚本身就成了故障源。其三，数值层监控的 ρ_k 统计应作为发布门禁的一部分：任何码本或级数变更在灰度期都要比对 ρ_k 分布与基线，末级 ρ_K 中位数上移超过阈值即自动停止放量。这条门禁之所以必要，是因为材料未给出可核验的质量数值，部署方无法用离线指标预判线上重建上限，只能靠在途残差链的实时统计做兜底。</p>\n<h3 id=\"paper-a-streamable-neural-audio-codec-with-2025-sec-46\">四十六 · 先把“基准”拆成六个可独立变化的轴</h3>\n<p>读这篇编解码器的任何性能表述，第一步不是看数字，而是确认它站在哪一组坐标上。实时通信编解码器的基准至少由六个轴张成：模型（量化级数 K、各级码本大小、因果卷积感受野与帧长）、硬件档位（B200 与 GB200 NVL72 的差别不在单卡算力，而在可用的 NVLink 5 域大小与可分摊的功耗预算）、batch（流式场景下 batch 的含义是并发会话路数，而非离线推理的样本堆叠）、并发（每路独立状态缓存）、指标口径（首包延迟、单帧处理耗时、吞吐、显存、功耗），以及测量边界（是否含码流打包、播放缓冲与网络抖动）。这六个轴任意一个变动，结论就换了一个含义。论文材料没有给出可核验的数值结果，因此本部分的任务不是复述数字，而是建立一套“数字怎么读”的判据：哪些量可以横向比较，哪些一提就不可比。</p>\n<p>关键判断在于：该编解码器的延迟模型是“单帧编码耗时 + 单帧解码耗时”，与音频总长解耦。任何声称“端到端延迟 X 毫秒”的表述，若不说明帧长、K、码本大小与是否计入播放缓冲深度，就无法与其他系统对齐。这是本部分所有讨论的锚点。</p>\n\n<h3 id=\"paper-a-streamable-neural-audio-codec-with-2025-sec-47\">四十七 · 首包延迟的正确分解与不可比的三种情形</h3>\n<p>首包延迟（TTFT 在语音编解码语境下的对应量）应写成可加分解，而不是一个笼统的端到端数字：</p>\n<div class=\"formula\">$$ T_{\\text{first}} = T_{\\text{frame\\_enc}} + T_{\\text{quant}} + T_{\\text{pack}} + T_{\\text{frame\\_dec}} + T_{\\text{buf}} $$</div>\n<p>其中量化项本身是串行的：</p>\n<div class=\"formula\">$$ T_{\\text{quant}} \\approx \\sum_{k=0}^{K} t_{\\text{NN},k} $$</div>\n<p>每级一次最近邻查询，级数 K 线性抬升该项。这意味着“把 K 从 2 提到 4 换取质量”在延迟账本上不是免费的：单帧处理耗时随 K 近似线性增长，首包延迟同向增长。工程上必须把 K 与帧长一起放进延迟预算里联合选取，而不是先定质量目标再补延迟。</p>\n<p>三种典型不可比情形：其一，一方报告“单帧编解码耗时”，另一方报告“含播放缓冲的端到端延迟”，后者多出 <span>T_buf</span>，缓冲越深抖动容忍越好但首包越晚，两者不在同一口径；其二，一方在空载下单路测量，另一方在满载并发下测量，后者包含状态缓存争用与码本查询的访存冲突，单帧耗时会被放大；其三，一方按离线模型的显存口径估算容量，另一方按每路状态缓存乘以并发数估算，前者会系统性低估。凡跨这三条边界引用数字，结论即失效。</p>\n<p>具体例子：一路 24 kHz 语音按固定帧长切分，若单帧编码加解码合计落在个位数毫秒量级，则首包可在首帧解码完成即输出；但若把 K 翻倍，量化项近似翻倍，首包预算被吃掉的部分必须从帧长或感受野里找回来。材料未给出具体毫秒数，因此这里只给结构，不给数值。</p>\n\n<h3 id=\"paper-a-streamable-neural-audio-codec-with-2025-sec-48\">四十八 · 吞吐、并发与显存：三个量的耦合关系</h3>\n<p>流式编解码器的吞吐不能按“帧/秒”孤立报告，必须绑定并发路数。设单路单帧处理耗时为 <span>t_f</span>，帧率为 <span>f</span>，则单路实时性约束是 <span>t_f ≤ 1/f</span>；系统在 N 路并发下的稳态吞吐上限近似为：</p>\n<div class=\"formula\">$$ \\Theta \\approx \\frac{N \\cdot f}{\\max(1,\\; N \\cdot t_f \\cdot f)} $$</div>\n<p>当 <span>N·t_f·f ≤ 1</span> 时吞吐随并发线性上升，超过该点后进入饱和，单帧耗时开始被争用拉长，首包延迟随之劣化。这条曲线解释了为什么“吞吐翻倍”的宣称必须附带并发点：同一个系统在低并发区和高并发区的斜率完全不同。</p>\n<p>显存侧，流式状态缓存是固定占用而非随音频长度增长，这是相对离线编解码器的结构性优势；但其总量与并发线性相关：</p>\n<div class=\"formula\">$$ M_{\\text{state}} \\approx N \\cdot \\left( S_{\\text{enc}} + S_{\\text{dec}} \\right) + M_{\\text{codebook}} $$</div>\n<p>码本常驻显存，多级小码本的设计使 <span>M_codebook</span> 远小于单级大码本，这是该工作可迁移到 Blackwell 显存预算的直接价值；但 <span>S_enc + S_dec</span> 随感受野与帧长增长，容量规划必须按“每路缓存 × 并发数”估算，而不是按模型参数量估算。用离线口径做容量规划会漏掉这一项，在 N 较大时误差显著。</p>\n<p>具体例子：在 GB200 NVL72 上做分离式部署时，编码与解码可落在不同实例以重叠首帧处理，此时状态缓存被拆到两侧，单侧显存压力下降但跨实例码流传输引入额外一跳；在 B200 单卡上做同卡编解码，省掉这一跳但两侧缓存叠加在同一显存池。两种拓扑的显存账本不同，吞吐与首包延迟的权衡点也不同。</p>\n\n<h3 id=\"paper-a-streamable-neural-audio-codec-with-2025-sec-49\">四十九 · 功耗与硬件档位：为什么“同模型不同档”不可直接比</h3>\n<p>Blackwell 部署中，功耗是容量规划的一等约束而非附属指标。同一编解码器在 B200 与 GB200 NVL72 上的表现差异，主要不来自单帧算力，而来自三处：可分摊的功耗预算、NVLink 5 域内可用的通信带宽、以及并发路数上限。多级量化的串行最近邻查询是访存密集型而非算力密集型，其能效更多取决于码本是否驻留于近端存储与查询是否命中缓存，而非峰值 FLOPS。因此“换更高档硬件”对这类负载的收益是有限的，除非并发规模同时提升以摊薄固定开销。</p>\n<p>可读的功耗口径应绑定“每路每帧能耗”而非整机功耗：</p>\n<div class=\"formula\">$$ E_{\\text{frame}} \\approx \\frac{P_{\\text{sys}} \\cdot t_f}{N} $$</div>\n<p>整机功耗除以并发再乘以单帧耗时，才是可跨档比较的量。只报整机功耗会把并发差异藏进分母里。材料未给出部署档位与功耗数值，因此这里只能给出口径而非结论：任何跨档比较若不同时给出 N 与 t_f，即不可比。</p>\n<p>具体例子：同一 K 与码本配置下，把并发从低档提到高档，<span>E_frame</span> 因分母变大而下降，但 <span>t_f</span> 因争用上升，两者部分抵消；净收益取决于系统处在吞吐曲线的哪一段。这正是“档位提升”不能简单等同于“每路成本下降”的原因。</p>\n\n<h3 id=\"paper-a-streamable-neural-audio-codec-with-2025-sec-50\">五十 · 指标口径的陷阱：哪些提升是机制性的，哪些是口径性的</h3>\n<p>把该工作的提升拆成两类。机制性提升有三条，均可从结构直接推出而不依赖实验数字：多级小码本替代单级大码本，降低码本查询与存储开销；因果卷积加帧间状态缓存，使解码按帧增量推进，首包延迟与音频总长解耦；状态缓存固定占用，显存不随音频长度线性增长。这三条是结构性的，换硬件、换并发都成立。</p>\n<p>口径性提升则是测量边界造成的表观差异，典型有四类：把“单帧耗时”与“端到端延迟”混报；在空载下测首包而在满载下测吞吐；用离线显存模型估算流式容量；把 K 增加带来的质量收益与延迟代价分开报告而不给折中曲线。识别方法很直接：看报告是否同时给出 K、帧长、码本大小、并发 N 与测量边界。缺任一项，提升幅度就不可横向引用。</p>\n<p>消融维度上，可关注的是 K、各级码本大小、因果卷积感受野与帧长对首包延迟与重建质量的联合影响。材料未给出消融数据，因此正确的读法是：把 K 视为延迟与质量的双向旋钮，把码本大小视为质量上限与显存占用的旋钮，把帧长视为延迟粒度与抖动容忍的旋钮，三者不能独立调。</p>\n<p>具体例子：若某报告称“质量提升而延迟不变”，需检查其是否在提升 K 的同时缩短了帧长或减小了感受野——这三者互为补偿，单看一项会得出错误结论。</p>\n\n<h3 id=\"paper-a-streamable-neural-audio-codec-with-2025-sec-51\">五十一 · 在 Blackwell 上落地这套口径的最小检查清单</h3>\n<p>部署前应按以下顺序核对，任一项缺失即判定该基准不可用于容量规划：</p>\n<ul>\n<li>模型轴：K、各级码本大小、帧长、感受野是否全部给出；码本是否常驻显存。</li>\n<li>硬件轴：B200 单卡还是 GB200 NVL72 域内；编解码是否分离部署；跨实例码流是否引入额外一跳。</li>\n<li>并发轴：报告吞吐时的 N 是多少；是否处于吞吐曲线饱和区之前。</li>\n<li>指标轴：首包延迟是否含播放缓冲；单帧耗时是否为空载值；显存是否按每路缓存乘并发估算。</li>\n<li>功耗轴：是否给出每路每帧能耗而非整机功耗。</li>\n</ul>\n<p>这套清单的工程价值在于把“不可比”提前暴露。该工作的结构优势——小码本降低查询与存储、状态缓存解耦音频长度——在 Blackwell 上是可复用的设计路径；但其多级串行查询对单帧延迟的线性抬升、小码本容量对重建上限的约束，以及状态缓存随并发线性增长的显存账本，同样是必须计入预算的代价。材料未给出可核验的吞吐、延迟与质量数值，因此在缺乏上述六轴信息时，不应把该工作直接引用为低延迟部署的证据，而应把它当作一个结构模板：先在自己的帧长、K、并发与硬件档位上重测单帧耗时与每路缓存，再决定容量与 SLO 余量。</p>\n\n<h3 id=\"paper-a-streamable-neural-audio-codec-with-2025-sec-52\">五十二 · 流式编解码器的容量边界：串行查询、状态缓存与不可比的“提升”</h3>\n<p>这套方案的系统代价不在算力峰值，而在两条与并发直接挂钩的线性项。第一条是单帧延迟：每帧必须串行完成 K 次最近邻查询，标量级一次、矢量级 K−1 次，后一级必须等前一级残差算出才能开始，因此单帧耗时可近似写成 <span class=\"formula\">$$ T_{\\text{frame}} \\approx T_{\\text{enc}} + \\sum_{k=0}^{K} T_{\\text{nn}}^{(k)} + T_{\\text{dec}} $$</span> 其中求和项随级数线性增长，首包延迟就等于这个值加上一次播放缓冲填充，与音频总长无关——这正是它与离线编解码器的分水岭，也是它无法靠“多堆几级换质量”无限优化的原因。第二条是显存：每路会话持有独立的编码器与解码器帧间状态缓存，容量规划只能按 <span class=\"formula\">$$ M_{\\text{total}} \\approx N_{\\text{sess}} \\times (S_{\\text{enc}} + S_{\\text{dec}} + M_{\\text{codebook}}) $$</span> 估算，码本常驻部分可被所有会话共享，状态缓存则不可，故并发路数上升时显存线性抬升，而单路显存不随音频时长增长。工程判断很直接：级数 K 由质量下限倒推、由首包 SLO 封顶，两者之间没有免费区间。</p>\n<p>由此产生三类典型失效。其一，把多级量化当成纯质量手段：级数增加确实让残差逐级逼近、重建上限抬高，但每帧串行查询次数同步增加，在固定帧长下直接吃掉首包预算，高并发时更会因 SM 占用与访存争用放大单帧耗时。其二，沿用离线编解码器的显存模型做容量规划：离线模型按整段音频的激活与上下文估算，而这里显存由并发路数乘以每路固定状态缓存决定，忽略后者会在压测中突然撞墙。其三，在材料未给出吞吐、延迟与质量数值的前提下，把该工作当作低延迟部署的可核验证据引用——论文只给出了机制层面的因果性与状态缓存设计，没有可复现的基准数字。</p>\n<p>因此读这类结果要先对齐口径。可比的前提是：同一帧长与帧率、同一量化级数 K 与各级码本大小、同一硬件档位与 batch/并发配置、同一指标定义（首包延迟是否含播放缓冲填充、单帧耗时是编码加解码还是仅解码、吞吐按路数还是按帧数计）。下表列出必须核对的维度与不可比时的典型偏差来源。</p>\n<table class=\"mini\"><thead><tr><th>口径维度</th><th>可比要求</th><th>不可比时的偏差来源</th></tr></thead><tbody><tr><td>帧长/帧率</td><td>固定帧长切分，逐帧触发</td><td>攒批会人为压低首包延迟</td></tr><tr><td>量化级数 K</td><td>级数与码本大小一致</td><td>级数不同则串行查询次数不同</td></tr><tr><td>并发/显存</td><td>按会话计状态缓存</td><td>共享码本与独占缓存混算</td></tr><tr><td>指标定义</td><td>首包含缓冲填充与否</td><td>TTFT 与单帧耗时被混用</td></tr></tbody></table>\n<p>落到 Blackwell 部署上，这条路径的价值在于把码本存储与查询开销压到可共享的小码本上，从而把显存预算让给并发状态缓存与 KV 侧资源；代价是串行查询链成为单帧延迟的下界，级数越多、码本越小，质量上限与延迟预算的张力越紧。真正决定能否上线的不是“比离线快多少”这类跨口径比较，而是给定帧长与 SLO 下 K 与码本大小的可行域，以及每路缓存乘并发数后的显存余量。</p>\n<h3 id=\"paper-a-streamable-neural-audio-codec-with-2025-sec-53\">五十三 · 迁移到别的编解码器：先看量化器的“可拆性”</h3>\n<p>把 RSVQ 这套方案搬到另一个神经音频编解码器上，第一步不是改代码，而是判断目标模型的量化器能否被拆成“标量粗量化 + 小码本残差细化”的多级结构。可拆性的判据有三条：量化前的特征维度是否足够高，使逐维标量量化不至于把相关性丢光；码本是否可以被替换而不破坏解码器对索引的语义依赖；解码器是否已经具备因果结构与状态传递能力。第三条最关键——如果目标解码器是离线非因果设计（例如依赖双向上下文或整段归一化），那么即便量化器换成 RSVQ，也无法获得按帧增量输出的能力，首包延迟仍然与音频总长挂钩。</p>\n<p>迁移时真正要改的是解码器的状态接口。因果卷积本身不自动带来流式能力，必须显式定义每层的帧间状态：卷积层保留感受野内的历史激活，归一化层保留滑动统计量，上采样层保留相位对齐的缓冲。这套状态集合的规模由感受野与通道数决定，而不是由音频长度决定。工程上应把状态缓存做成每路会话独立的结构体，随会话创建而分配、随会话结束而释放，避免用全局池化缓存导致并发路数上升时相互污染。</p>\n<div class=\"formula\">$$ \\text{单帧延迟} \\approx T_{\\text{enc}} + K \\cdot T_{\\text{nn}} + T_{\\text{dec}},\\quad \\text{显存} \\approx N_{\\text{sess}} \\cdot S_{\\text{state}} + S_{\\text{codebook}} $$</div>\n<p>其中 $K$ 为残差级数，$T_{\\text{nn}}$ 为单次最近邻查询耗时，$N_{\\text{sess}}$ 为并发会话数，$S_{\\text{state}}$ 为每路状态缓存字节数。这个式子给出迁移的第一个代价判断：级数 $K$ 是串行乘数，不是并行可摊薄的开销。把 RSVQ 迁到一个原本用单级大码本的模型上，若目标模型帧率更高（帧长更短），单位时间内触发的串行查询次数随之上升，单帧延迟预算被压缩得更紧，此时应优先削减 $K$ 或缩小码本维度，而不是照搬原级数。</p>\n<p>具体例子：某离线编解码器使用单级 1024 项、64 维的矢量量化，查询一次即完成。迁到 RSVQ 后改为 8 级、每级 64 项小码本，单帧查询次数从 1 变为 8，码本常驻显存从 1024×64 个浮点数降为 8×64×64，存储下降但串行延迟上升。若该模型帧长为 20 ms，则每帧必须在 20 ms 内完成编码、8 次查询与解码，任何一级查询的访存抖动都会直接吃掉首包预算。</p>\n\n<h3 id=\"paper-a-streamable-neural-audio-codec-with-2025-sec-54\">五十四 · 迁移到别的领域：状态缓存的语义必须重新定义</h3>\n<p>RSVQ 与因果状态缓存这套组合在语音上成立，是因为语音的短时平稳性使帧间感受野有限、历史状态可压缩。迁到音乐、环境声或长时音频事件检测时，感受野需求显著变长：音乐的和声进行、环境声的混响拖尾都要求状态缓存覆盖更长的历史。此时若沿用语音场景的缓存深度，重建会出现帧边界处的相位断裂与能量突变；若加长缓存，$S_{\\text{state}}$ 随感受野线性增长，并发容量被直接压缩。</p>\n<p>迁到非音频领域则要更谨慎。RSVQ 的本质是“用多级小码本逼近连续特征”，它成立的前提是特征分布在各维度上近似独立、残差逐级可收敛。对于维度间强相关且残差分布重尾的特征（例如某些视觉 latent 或跨模态联合嵌入），第一级逐维标量量化会引入较大的粗量化误差，后续小码本需要更多级才能收敛，串行延迟随之膨胀。判断是否适用，应看第一级标量量化后的残差能量占比：若残差能量与原始特征能量同量级，说明标量粗量化几乎没起作用，多级结构退化为串行小码本堆叠，收益消失而延迟照付。</p>\n<ul>\n<li>适用信号：特征维度高、维度间相关性弱、残差随级数快速衰减。</li>\n<li>不适用信号：维度间强相关、残差重尾、解码器依赖双向上下文。</li>\n<li>需改造项：状态缓存的感受野深度、码本维度的分组方式、帧长与级数的联合裁剪。</li>\n</ul>\n<p>代价层面，跨领域迁移最容易被低估的是播放缓冲深度。语音对话可以容忍几十毫秒的抖动缓冲，音乐播放或实时合奏对抖动更敏感，缓冲深度被压缩后，任何一次单帧处理超时都会直接表现为欠载。因此在非语音领域部署时，应把 $K$ 的取值与最坏情况单帧耗时绑定，而不是按平均耗时估算。</p>\n\n<h3 id=\"paper-a-streamable-neural-audio-codec-with-2025-sec-55\">五十五 · 规模上限：三个独立的饱和点</h3>\n<p>这套方案的上限不在模型参数量，而在三个互相独立的饱和点。第一个是码本容量的饱和：小码本降低存储与查询开销，但残差逐级逼近的重建上限受每级码本容量约束，级数 $K$ 增加可以补偿容量，代价是串行延迟线性上升。存在一个 $K$ 使质量增益的边际收益低于延迟预算的边际损失，超过该点继续加级只增加延迟不增加可用质量。</p>\n<p>第二个是并发容量的饱和：显存随 $N_{\\text{sess}} \\cdot S_{\\text{state}}$ 线性增长，而 $S_{\\text{state}}$ 由感受野与通道数决定，无法通过批处理摊薄——每路会话的状态是独立的，不能像 KV cache 那样跨请求共享前缀。这意味着该方案的容量规划是纯线性的，没有连续批处理带来的摊薄效应。在 Blackwell 这类大显存平台上，单卡可承载的会话数由状态缓存而非权重决定，权重只占固定一份。</p>\n<div class=\"formula\">$$ N_{\\text{sess}}^{\\max} \\approx \\frac{M_{\\text{free}} - S_{\\text{weights}} - S_{\\text{codebook}}}{S_{\\text{state}}} $$</div>\n<p>第三个是单帧延迟的饱和：单帧处理耗时由编码、$K$ 次串行查询与解码三段构成，三段中任何一段无法与帧到达节奏对齐，就会累积成播放缓冲欠载。帧长越短，对齐余量越小；当帧长接近单帧处理耗时的量级时，系统失去抖动容忍能力。这三个饱和点中任意一个先到，都构成实际规模上限，容量规划应取三者最小值。</p>\n<p>具体例子：一路会话的状态缓存若为固定若干 MB 量级，单卡剩余显存扣除权重与码本后，可承载的会话数由除法直接给出；若业务要求并发翻倍，只能增加卡数或削减感受野，没有第三条路。这与基于 KV cache 分页、前缀共享的 LLM 推理容量模型有本质区别——后者可以通过调度把显存利用率做高，前者只能靠线性扩容。</p>\n\n<h3 id=\"paper-a-streamable-neural-audio-codec-with-2025-sec-56\">五十六 · 与 Blackwell 推理栈的接口边界</h3>\n<p>迁到 Blackwell 部署时，这套方案与既有推理栈的接口边界需要明确。量化器的小码本查询是访存密集型而非计算密集型操作，最近邻查询的瓶颈在码本读取带宽而非 MMA 吞吐，因此不应期待 tcgen05 或 2-SM MMA 带来收益；真正能受益的是把多级查询中的独立维度分组映射到向量化访存，以及把状态缓存的读写放在靠近计算单元的位置以减少往返。NVFP4/FP8 量化对码本本身意义有限——码本项是索引目标，量化码本会引入查询误差并破坏索引语义，精度收益应放在编码器特征与解码器激活上。</p>\n<p>与连续批处理的接口同样需要重新审视。LLM 推理的连续批处理把不同请求的 token 拼进同一批次以摊薄权重读取，而这套编解码器的每路会话携带独立状态，批处理只能在“同一帧时刻到达的多路会话”之间做维度拼接，无法跨帧重组。这决定了它的调度器更接近固定节拍的流水线，而不是动态拼批的 token 调度器。工程判断是：不要把它塞进为 LLM 设计的调度框架里期待自动摊薄，应按会话数做静态容量分配，把调度复杂度留给上游的 TTS 或对话系统。</p>\n<p>与分离式预填/解码的类比也要克制。编解码器的“首帧”确实类似预填，但它的首帧工作量不随输入长度增长——每帧工作量恒定，没有 prefill 与 decode 的算力不对称。因此把分离式部署套用到编解码器上，收益仅来自编码与解码在时间上的重叠，而非算力阶段的解耦。代价是两段之间的码流传输引入额外一跳延迟，在首包预算紧张时应优先考虑同进程内流水而非跨节点分离。</p>\n\n<h3 id=\"paper-a-streamable-neural-audio-codec-with-2025-sec-57\">五十七 · 不适用场景与判断准则</h3>\n<p>有三类场景应明确判定为不适用。第一类是要求极低码率的高保真音乐传输：小码本容量约束使残差逼近在高码率需求下需要更多级数，串行延迟与质量目标直接冲突，此时单级大码本配合离线或半离线解码更合适。第二类是输入不可按固定帧长切分的场景，例如任意长度的离线转写或非实时批量处理：流式状态缓存的固定显存开销与逐帧推进的串行结构在批量场景下没有收益，反而损失了批处理摊薄的机会。第三类是解码器必须依赖未来上下文的模型，因果化改造会损失重建质量，迁移的净收益为负。</p>\n<p>判断准则可以收敛为三个问题：目标模型的解码器能否在只依赖历史状态的条件下达到可接受的重建质量；目标场景的帧长是否给单帧处理留出足够的抖动余量；并发容量是否由状态缓存而非权重决定并且业务能接受线性扩容。三个问题中任一为否，就应放弃整体迁移，只借用其中可分离的部分——例如仅借用多级小码本降低码本存储，保留原解码器的非因果结构并接受离线延迟。</p>\n<p>最后落在工程判断上：这套方案的可迁移价值集中在“把大码本拆成多级小码本以降低存储与查询开销”与“用显式状态缓存换取按帧增量输出”两个机制上，而它的边界由串行查询的线性延迟、状态缓存的线性显存与码本容量的质量上限三者共同划定。在 Blackwell 上做容量规划时，应把每路会话的状态缓存字节数作为第一类容量参数来测量，把级数 $K$ 作为延迟预算里的串行乘数来裁剪，而不是把该工作当作低延迟部署的现成证据直接引用——材料未给出可核验的吞吐、延迟与质量数值，任何容量数字都必须来自本机实测。</p>\n<figure class=\"diagram\" data-fig=\"paper-family\"><svg style=\"max-width:746px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 746.0 138\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><text x=\"136.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">上游 · 站在谁肩上</text><rect x=\"38.0\" y=\"44.0\" width=\"196.0\" height=\"35.0\" rx=\"6\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><text x=\"48.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#b45309\" font-weight=\"500\" text-anchor=\"start\">领域入口（无上游）</text><text x=\"380.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">本文</text><rect x=\"282.0\" y=\"44.0\" width=\"196.0\" height=\"52.0\" rx=\"6\" fill=\"#e9eff5\" stroke=\"#d6e2ec\" stroke-width=\"1.2\"/><text x=\"292.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#163a5a\" font-weight=\"500\" text-anchor=\"start\">A Streamable Neural Audio </text><text x=\"292.0\" y=\"78.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#163a5a\" font-weight=\"500\" text-anchor=\"start\">Codec with Re…</text><text x=\"624.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">下游 · 被谁接走</text><rect x=\"526.0\" y=\"44.0\" width=\"196.0\" height=\"35.0\" rx=\"6\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><text x=\"536.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#15803d\" font-weight=\"500\" text-anchor=\"start\">暂无下游记录</text><line x1=\"238.0\" y1=\"74.0\" x2=\"271.0\" y2=\"74.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 270.0 69.5 L 270.0 78.5 L 278.0 74.0 Z\" fill=\"#d8d3c6\"/><line x1=\"482.0\" y1=\"74.0\" x2=\"515.0\" y2=\"74.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 514.0 69.5 L 514.0 78.5 L 522.0 74.0 Z\" fill=\"#d8d3c6\"/><text x=\"380.0\" y=\"128.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.0\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"middle\">2025 · arXiv preprint</text></svg><figcaption><b>家谱</b> · A Streamable Neural Aud… 的上游问题、本文位置与下游继承；箭头表示方法/问题的传递，不是时间先后。</figcaption></figure>\n<table class=\"mini\" data-fig=\"paper-exp\"><caption>实验速查：这篇论文拿什么数据、和谁比、提升来自哪里</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>数据集</td><td>材料未给出具体数据集名称</td></tr><tr><td>基线</td><td>材料未给出具体基线系统</td></tr><tr><td>主要结果</td><td>材料未给出可核验的数值结果；从机制上看，残差标量-矢量量化以多级小码本替代…</td></tr><tr><td>消融</td><td>材料未给出消融实验数据；可关注的消融维度为量化级数 K、各级码本大小、因果…</td></tr><tr><td>局限</td><td>材料未给出实验限制说明；可推断的工程代价包括：多级量化增加每帧的串行查询次…</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：papers/paper-a-streamable-neural-audio-codec-with-2025 · 共 9 个片段</p>\n";break;}}})();
